quests[66972] = { id = 66972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alter Steinhauer", sourceObjective = "Erlegt den alten Steinhauer beim Lager Antonidas.", progress = "Ist es vorbei?", completion = "Das bereitet mir keine Freude.\n\nAber ich werde seinen Stoßzahn an einem Ehrenplatz aufhängen.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66989] = { id = 66989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfreiche Ernte" }
quests[66997] = { id = 66997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krippenspiel", description = "Ich bin so dankbar, dass Lasztak die Berufung eines Welpenhüters angenommen hat! Insbesondere, da gerade so viele dieser kleinen Schätzchen ihre Zähne kriegen.\n\nDarüber hinaus stehen den Krippengärten noch andere Herausforderungen bevor. Die Welpen sind gestresst und die Hüter sind... nun, noch gestresster als sonst.\n\nBitte, wenn Ihr mal einen Moment entbehren könnt, dann besucht mich unten in den Gärten. Wir könnten Eure Hilfe auch brauchen!", sourceObjective = "Trefft Euch mit Vaeros im Garten der Rubinlebensbecken.", completion = "Gut, dass Ihr da seid! Ihr habt ja vielleicht die Bienen auf dem Weg hierher bemerkt. Wir müssen etwas gegen sie unternehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66998] = { id = 66998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer mit... Wasser bekämpfen", description = "In all den Jahren, in denen ich mich um die Lavaelementare gekümmert habe, habe ich sie nie in diesem Zustand gesehen! Wir können sie kaum in ihrer Höhle halten.\n\nHabt Ihr einen Moment Zeit? Wir sichern den Ausgang, während Ihr ihre Reihen drinnen ausdünnt.\n\nHier, nehmt diese Wasserelementarflasche mit.\n\nIch habe immer ein paar Wasserelementarflaschen dabei, wenn ich mich der Lavaelementare annehme. Natürliche Feinde sind immer eine gute Ablenkung!", sourceObjective = "Tötet Lavaelementare in der Ausbrechenden Höhle.", completion = "Ich danke Euch für diese kurze Verschnaufpause. Die Arbeit einer Verwalterin ist niemals getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[67002] = { id = 67002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slalom des Azurblauen Gebirges", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67003] = { id = 67003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slalom des Azurblauen Gebirges - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67004] = { id = 67004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Dinge in großen Kisten", description = "Durch unsere Bemühungen haben wir alles, was wir brauchen, um einen Tresor des Erdwächters zu öffnen. Unter der Zitadelle gibt es mehrere Tresore. Findet einen und ich werde Euch belohnen.\n\nIch habe Ketten geschmiedet, um ihn zu transportieren. Wenn Ihr ihn herkriegt, können wir uns die Reichtümer teilen.\n\nDer Tresor könnte schon transportiert werden. Ich habe auch andere ausgesandt, um ihn zu suchen.", sourceObjective = "Findet einen Tresor des Erdwächters für mich und bringt ihn her, damit wir uns den Inhalt teilen können.", completion = "Ausgezeichnete Arbeit, {name}. Mit etwas Glück können wir schon bald noch mehr Tresore öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67005] = { id = 67005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protodrachenzähmen leicht gemacht" }
quests[67006] = { id = 67006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löschen der Flamme" }
quests[67007] = { id = 67007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivassistenz", description = "<Die klare, saubere und mit elegantem Strich geschriebene Schrift verblasst schnell vor der feuchten, verschmierten Tinte des Pergaments und einem Geruch, der an ein verschüttetes, vergorenes Getränk erinnert.>\n\nABENTEUERSUCHER, ARCHIVIERUNGSLIEBHABER\n\nDie Archive wenden sich an alle, die Antworten suchen, sich nach Entdeckungen sehnen und die Geheimnisse der Vergangenheit und vielleicht sogar der Zukunft lüften wollen!\n\nDieser Aufruf ist nichts für zaghafte oder wankelmütige Personen.\n\nNur wissbegierige und mutige Abenteurer dürfen sich bewerben.\n\n- Kemora", sourceObjective = "Sprecht mit Kemora bei den Archiven in Valdrakken.", completion = "<Kemora dreht sich anmutig zu Euch um. Bevor sie spricht, mustert sie Euch mit einem Lächeln auf den Lippen von den Zehenspitzen langsam bis nach oben, bis sich Eure Augen und ihr ruhiger Blick treffen.>\n\nSind es auch Antworten, nach denen Ihr sucht, {race}?\n\nIch bin bereit, mit Euch zu sprechen, wenn Ihr der Herausforderung gewachsen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[67009] = { id = 67009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flunkerunfug" }
quests[67010] = { id = 67010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Überkochen" }
quests[67011] = { id = 67011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteuergeschichte: Geschmolzener Kern", description = "Ihr wollt mir also eine Geschichte über Eure Abenteuer erzählen?", sourceObjective = "Erzählt der Ältesten Poa von Euren Abenteuern im Geschmolzenen Kern.", sourceObjectiveStatus = "unverified-source-field" }
quests[67012] = { id = 67012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Flussbestien fliegen" }
