quests[67031] = { id = 67031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vakthrosaufstieg", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67032] = { id = 67032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vakthrosaufstieg - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67033] = { id = 67033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung zusammensetzen", description = "Die Primalisten waren hinter den Kirin Tor her, seit wir im Azurblauen Gebirge angekommen sind. Sie verabscheuen unseren Umgang mit der Arkanmagie.\n\nIch werde Kalecgos mitteilen, dass er aus den Azurarchiven zurückkehren soll. Bis dahin müssen wir sie aufhalten.\n\nAnscheinend wurde eines unserer arkanen Hauptverteidigungssysteme während des Angriffs zerstört. Bringt mir die Teile, dann kann ich es wieder zusammensetzen.", sourceObjective = "Findet 3 Teile des Arkanstrahlers.", progress = "Habt Ihr alle Teile? Ich weiß noch genau, wie sie zusammengesetzt waren, die Reparatur sollte also kein Problem darstellen.", completion = "Ausgezeichnet. Ich werde gleich mit dem Ritual für die Reparatur beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67034] = { id = 67034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Wind und Wasser", description = "Im Osten gibt es eine großartige Drachenquelle, die als Nistgrund für wilde Adler dient. Die Federn, die sie verlieren, behalten ihre Magie für eine ganze Weile und werden in vielen Ritualen genutzt.\n\nDie Gegend beheimatet auch wilde Elementargeister, und ihre Kerne sind ebenfalls nützlich.\n\nBringt mit eine Handvoll von beidem... und denkt daran, dass die Adler heilig sind. Ich werde keine Federn annehmen, für die sie verletzt wurden.", sourceObjective = "Sammelt Reagenzien von den Tosende Drachenquellen.", progress = "Habt Ihr alles gefunden?", completion = "Wir werden diese Reagenzien nutzen, um neue Mitglieder unseres Klans zu initiieren. Ich werde diese Schuld begleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67035] = { id = 67035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrung des Wissens", description = "Grüße, {race}. Ich bin Althanus. Ich wünschte, wir hätten uns in einer weniger... chaotischen Zeit kennengelernt.\n\nWir haben den Kirin Tor geholfen, die Geschichte dieses Ortes zu studieren, als plötzlich die Primalisten angriffen.\n\nIch fürchte, dass noch einige Folianten da draußen sind und Gefahr laufen, bei diesem entsetzlichen Überfall zerstört zu werden.\n\nIch bitte Euch, diese Folianten zu bergen! Wenn sie zerstört wurden, ist die Geschichte dieses Ortes verloren.", sourceObjective = "Findet 4 uralte Folianten in der Nähe des Lagers Antonidas.", progress = "Habt Ihr die Folianten?", completion = "Welche Erleichterung! All dieses Wissen zu verlieren... Das könnte ich nicht ertragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67036] = { id = 67036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Kirin Tor", description = "Ich habe die Teile des Geräts zusammengesetzt, die Ihr geborgen habt.\n\nPlatziert es in der Nähe von Khadgar und nutzt es, um die Primalisten zurückzuschlagen!\n\nWir müssen nur noch etwas länger durchhalten, bis Kalecgos kommt.", sourceObjective = "Verwendet den Arkanstrahler, um Khadgar im Kampf gegen die Primalisten zu unterstützen.", progress = "Haltet noch etwas länger durch...", completion = "Ich bin froh, dass der Angriff zurückgeschlagen wurde... Aber wir scheinen uns einen Plan überlegen zu müssen, wie wir Kalecgos in den Azurarchiven helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[67039] = { id = 67039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erstaunliche Reise", description = "Einige Haustiere des Klans sind auf der letzten Reise zwischen den Lagern verschollen. Sie sind keine Jagdtiere, deswegen bezweifle ich, dass sie da draußen alleine zurechtkommen!\n\nKönntet Ihr vielleicht nach ihnen suchen? Sie sind vielleicht keine Jagdpartner, aber sie sind dennoch wichtige Klanmitglieder!", sourceObjective = "Findet die verschwundenen Tiere.", completion = "Sie sind alle vor Euch zurückgekehrt. Den Winden sei Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[67044] = { id = 67044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Heldensage: Yanikk", description = "Lasst mich Euch die Geschichte von Yanikk erzählen.", sourceObjective = "Lauscht der Geschichte von Yanikk.", sourceObjectiveStatus = "unverified-source-field" }
quests[67047] = { id = 67047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wärme gegen das Frösteln", description = "Ich glaube, die Pflanze, die Ihr sucht, hat einen schmalen Stängel und rote Blätter.\n\nIhr werdet es jedoch schwer haben, nicht auf diese garstigen Krabbeltiere zu stoßen, während Ihr Pflanzen sammelt. Ich würde Euch raten, ihnen aus dem Weg zu gehen, so gut Ihr könnt, oder immer ein scharfes Schwert zur Hand zu haben, wenn das nicht geht.\n\nUnd lasst Eure Drachenfreundin wissen, dass sie mich zur Wiedergutmachung auf eine oder zwei Tassen von dem Zeug einladen kann, wenn ich wieder in der Stadt bin.", sourceObjective = "Sammelt 12 Kaltbisspfeilblätter.", progress = "Wenn man ihn genau richtig ziehen lässt, erfüllt Kaltbisstee einen für Stunden mit Wärme.", completion = "Ah! Das ist eindeutig Kaltbisspfeilblatt! Meine Nasenlöcher sind entzückt!\n\nAusgezeichnete Arbeit, {name}! Ich bin sicher, unsere ehrwürdigen Gäste werden Euch mit jedem Schluck voller Wärme lobpreisen. Und nicht zu vergessen, diese köstlichen kleinen Kuchen, die Schnabuli und Schleimhals gebacken haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[67050] = { id = 67050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostbeulen: Ursachen und Symptome", description = "In den Totems Elemente leben, {race}. Lasst frei und brecht Eis. Befreit Tuskarrfreunde!", sourceObjective = "Platziert die Totems und befreit die gefangenen Tuskarrjäger im Azurblauen Gebirge.", completion = "Ihr habt WAS getan?! Pah... Das spielt derzeit keine Rolle. Das hier ist noch nicht vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[67051] = { id = 67051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenaugen", description = "Wir wissen, dass die Djaradin uns direkt angreifen werden, aber es gibt noch andere Gefahren da draußen, die mir Sorgen bereiten. Gefahren, die nicht ganz so offensichtlich sind.\n\nIch habe drei Drachen losgeschickt, welche die Umgebung erkunden und potenzielle Gefahren lokalisieren sollen.\n\nTrefft Euch mit ihnen und sammelt ihre Berichte ein. Kehrt anschließend zu mir zurück, damit wir uns auf das, was die Djaradin geplant haben, bestmöglich vorbereiten können.", sourceObjective = "Sprecht mit Baskilan, Vazallia und Zepharion in den umliegenden Gebieten.", progress = "Was habt Ihr entdeckt?", completion = "Dank Euch sind wir besser darauf vorbereitet, was die Djaradin uns entgegensetzen wollen.\n\nWir werden unsere Augen stets offen halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[67053] = { id = 67053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Frieden eine Chance", sourceObjective = "Stellt Euch den Vertretern der Horde vor.", completion = "<Kriegsherrin Breka Grimmaxt begrüßt Euch.>\n\nKapitänin Garrick beweist einmal mehr ihre Ehrenhaftigkeit, indem sie Euch zu mir schickt.", sourceObjectiveStatus = "unverified-source-field" }
quests[67062] = { id = 67062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftürmende Konflikte" }
quests[67063] = { id = 67063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "10.000 Jahre des Bratens", description = "Gewürze? Oh! Ihr müsst zu der großen alten Drachenköchin gehör'n. Die mit dem kleinen Entenkoch auf dem Kopf.\n\nDie Djaradin sammeln Pulver, würzige Lavagewürze, von den feurigen Elementaren da unt'n.\n\nSchaut mich nich' so an! So nennen die Djaradin die nun mal, nich' ich!\n\nViel Glück da unten. Ich würd nich' allein geh'n, wenn ich Ihr wär.", sourceObjective = "Sammelt 30 würzige Lavagewürze.", progress = "Ich wünschte, ich könnte mit einem der Djaradinköche sprechen. Sie müssen eine ganz eigene, vielfältige kulinarische Geschichte haben. Wenn nicht mein eigenes Volk... eine Zutat wäre.", completion = "Riechen die nicht absolut wunderbar!\n\nGeben wir dem Fleisch eine Aspektbehandlung! Wir werden erstklassige Streifen bekommen, die Euch mariniert, gebraten und am Spieß direkt in den Mund serviert werden. Eure Geschmacksknospen werden zum ersten Mal richtig befriedigt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[67064] = { id = 67064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandernde Delikatesse", description = "Oh, Rumiastrasza! Ich hatte einen wunderbaren Abend mit den Dryadenschwestern Celina und Felina, als wir für sie gekocht haben.\n\nDer Tang, den wir gegessen haben, ist eine einzigartige Art, glimmender Wandertang genannt. Feschfischschwärme entlang der ganzen Küste ernähren sich davon. Ich wäre nicht überrascht, wenn sie Euch angreifen, während Ihr versucht, ihre Nahrungsquelle am Meeresboden zu pflücken.\n\nRichtet den Köchen meine besten Grüße aus, wenn Ihr sie seht. Sie sind hier in unserer Zuflucht stets willkommen.", sourceObjective = "Sammelt 10 glimmende Wandertangknollen.", progress = "Ich war den ganzen Tag vom Duft frischer Beeren umgeben. Es war ein wundervoller Nachmittag, {name}.", completion = "Ja! Glimmender Wandertang! Der köstliche, grasige Geschmack von der Schattenzuflucht.\n\nIch muss schon sagen, das Aroma erinnert mich an meine Jugend. Ich habe mich mit einem bescheidenen Wächter eines Portals zum Smaragdgrünen Traum angefreundet und war sofort bezaubert von der Vielfalt an fremdartigen Zutaten, die bei seinem Posten wuchsen. Dieser Tang verströmt dieselben, süßen Noten dieser herrlichen Welt, an die ich mich erinnere!\n\nHabt Dank, {name}. Ihr habt dieser alten Köchin heute eine Nostalgiebeilage zu ihrem Mahl serviert.", sourceObjectiveStatus = "unverified-source-field" }
quests[67065] = { id = 67065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futurist-frische Fungi", description = "Ein köstlicher Pilz? Alternative Zukunftslinien sind keine Vorratsschränke, die man mal eben für einen Vormittagssnack plündert.\n\nDennoch... Ich würde lügen, wenn ich sage, ich hätte nie davon geträumt, Rumis und Schnabulis Kochkünste noch einmal zu kosten.\n\nAlso gut! Ihr habt meine Erlaubnis, das Portal zu durchschreiten, doch ich würde Euch raten, nicht allein zu gehen.\n\nMeine Wächter haben bereits von diesen dunklen Pilzen gesprochen. Anscheinend bleiben sie nie lange am selben Ort. Was auch immer das heißen mag.", sourceObjective = "Fangt 7 zeitversengte Trüffler in der Zukunft der Primalisten.", progress = "Schnabuli hat mir so lange nichts von diesen wunderbaren Pilzen erzählt!\n\nWas verheimlicht Ihr mir noch, Ihr wundervoller kleiner Koch!", completion = "Die... sind... GRANDIOS!!\n\nNoch nie habe ich so unglaubliche Pilze gesehen! Die muss ich sparsam verwenden. Oder nicht! Wer weiß?!\n\nIch bin froh zu hören, dass die gute Sinjoirmi wohlauf ist. Ich würde in der Zukunft mehr als gerne wieder für sie kochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67066] = { id = 67066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köstlichkeiten zum Abtauchen", description = "Rumi und Schnabuli?\n\nGrundgütiger, das ist so lange her. Mit einem Kochduo aus Drache und Ente Fisch zu essen, klingt wie der Anfang einer Geschichte, die die Älteste Poa den Kindern erzählt. So ein Ereignis lässt sich nur schwer vergessen!\n\nDer Fisch war ein pikanter Deviantbandfisch, ein Topfavorit der Tuskarr! Sie sind selten, aber es gibt sie gleich hier vor der Küste.\n\nDoch ich warne Euch: Die Azurzähne sind in der Balz. Diese blutdurstigen Biester beißen Euch glatt ein Stück ab, wenn Ihr Euch an ihrer liebsten Knabberei zu schaffen macht.", sourceObjective = "Fangt einen pikanten Deviantbandfisch.", progress = "Schnabuli ist ein unfassbarer Angler. Er braucht nicht einmal eine Angelrute!", completion = "Oohoo! Riecht Ihr das? Es gibt nichts Frischeres als Fisch frisch aus dem Meer!\n\nSchnabuli und ich müssen einfach noch einen Sommer in Iskaara verbringen. Es gibt einfach keinen besseren Weg, mehr über eine Zutat zu erfahren als von den Handwerkern, die sie bereitstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67067] = { id = 67067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren im Springmaislabyrinth", description = "Es gibt eine Drachenköchin in Valdrakken? Wirklich? Ich muss sie bitten, meine Bogenlichtsuppe zu probieren! Es ist ein altes Familienrezept.\n\nIch kenne die Pflanze, von der Ihr sprecht. Sie wächst bei den Flüssen hier in der Gegend, aber sie hat einige Probleme verursacht.\n\nDie Stängel von Springmais scheinen die Nahrungsgrundlage vieler Käfer und kleiner Salamanther zu sein, die wiederum die natürliche Beute von Flunkern sind. Das ist nicht so schlimm, wenn man sie von Weitem sehen kann, aber einige von ihnen sind richtig verstohlen.\n\nIch an Eurer Stelle würde die Augen offen halten.", sourceObjective = "Sammelt 15 Stängel von wildem Springmais.", progress = "Ich habe Schnabuli getroffen, als er gerade einen riesigen Flunker über einer offenen Kohlengrube gegrillt hat. Der räudige Hüpfer ist ihm den ganzen Weg von der Grotte zu den Lebensbecken gefolgt, wo er ihn dann gemeinsam mit ein paar Wachen überwältigt hat.\n\nNatürlich hat er im Gegenzug das leckere Essen mit ihnen geteilt!", completion = "Ich schwöre, {name}, die Geschmacksnoten, die dieser Springmais entfaltet, sind wahrhaft revolutionär! Schnabuli sagt, das läge an den Lavaströmen entlang der Küste und dem einzigartigen Boden, der daraus entsteht.\n\nIch habe gelernt, dass man in fast allen Angelegenheiten besser auf ihn hören sollte... kulinarisch oder nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[67068] = { id = 67068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier mit einer Brise Salz", description = "Brisenjäger? Oh, diese Falken sind problematisch. Erst vor Kurzem hat unsere Stallmeisterin Marren beim Versuch einen von ihnen zu zähmen, fast den Tod gefunden.\n\nSie ist sehr stolz, deswegen hat sie es auf den Brisenjäger geschoben. Sie meinte, wenn er nicht gedacht hätte, seine Eier wären in Gefahr, wäre er nicht so aggressiv gewesen und hätte sie über die Klippe gedrängt.\n\nIch schätze, das heißt, dass Ihr die Eier, nach denen Ihr sucht, dort finden könnt? Es war östlich von hier, gleich um den Berg.", sourceObjective = "Sammelt ein Brisenjägerei ein.", progress = "Anscheinend habt Ihr ein paar Kratzer abbekommen, aber Ihr habt das Ei.\n\nMacht Euch keine Gedanken um Euren Stolz oder so! Sogar ein Drache meiner Größe würde sich nicht alleine an eins ihrer Nester wagen.", completion = "Wunderbar!\n\nSchnabuli und ich werden einen so leckeren Kuchen backen, dass Euer Gaumen das Singen lernt! Er wird luftiger als Luft, saftig wie eine Sonnenfrucht, aber mit einer knusprigen Textur.\n\nIhr werdet Euch selbst wie ein Brisenjäger fühlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[67071] = { id = 67071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was für eine lange, süße Reise", description = "{name}! Schnabuli und ich haben gerade nach Euch gesucht!\n\nWir danken Euch aus tiefstem geflügeltem Herzen.\n\nWir haben das Rubinfestmahl ins Leben gerufen, um die kulinarische Kultur der Inseln mit allen Völkern Azeroths zu teilen und auch von ihnen zu lernen. Wir haben Euch ganz schön von einem Ende unseres geliebten Kontinents zum anderen gejagt, aber Ihr habt geholfen, unseren Traum von dieser Versammlung für alle Besucher wahr zu machen.\n\nWir zählen Euch zu unseren engsten Freunden und möchten Euch etwas schenken. Nehmt das oberste Buch von unserem Hort hinter dem Kessel.", sourceObjective = "Sprecht mit Rumiastrasza.", progress = "Unser Hort liegt gleich hinter dem Kessel.\n\nKeine Sorge, wir haben die Siegelverzauberung und tödlichen magischen Fallen für Euch deaktiviert.", completion = "Fangt Ihr einen Fisch für einen Sterblichen, ist er für einen Tag ernährt.\n\nDoch lehrt Ihr einen Sterblichen das Kochen, hat er sein Leben lang zu essen.\n\nGebt einem Sterblichen Euer bestes Rezept, dann wird er jedes Mal an Euch denken, wenn er es kocht. Hoffen wir zumindest.\n\n<Schnabuli und Rumi schenken Euch ein Lächeln, wie es nur von guten Freunden kommen kann.>\n\nKommt gern jederzeit zurück, {name}! Das Essen geht auf uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[67073] = { id = 67073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rote Dämmerung", description = "Wir sind so kurz davor, unsere Kräfte wiederzuerlangen... Sollte Raszageth erfolgreich sein, bevor unsere Kräfte zurückkehren, dann fürchte ich, dass Azeroth eine dunkle Zukunft droht.\n\nDas dürfen wir nicht zulassen, {name}!\n\nSchnell, Ihr müsst Alexstrasza finden und ihr helfen, bevor alles verloren ist!", sourceObjective = "Findet Alexstrasza.", completion = "Raszageth und ihre Verbündeten müssen aufgehalten werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[67074] = { id = 67074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk aus Silber", description = "Kurz vor seinem Tod gab Hüter Tyr uns eine Drachenschuppe aus reinstem Silber. Wir haben sie während unserer Abwesenheit in den Gewölben von Valdrakken gelagert, aber ich glaube, es ist an der Zeit, sie wieder zu teilen.\n\nWir wissen zwar nicht, was ihr Zweck ist, aber sie war schon immer ein Symbol der Einheit und der Freundschaft. Als <wahrer Verbündeter/wahre Verbündete> der Drachen möchten wir sie mit Euch teilen. Sprecht mit mir, wenn Ihr bereit seid, {name}.", sourceObjective = "Sprecht mit Alexstrasza, um Tyrs Geschenk zu enthüllen.", completion = "Ich danke Euch, {name}, dass Ihr ein Verbündeter seid, dem wir solch wichtige Angelegenheiten anvertrauen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[67075] = { id = 67075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die innere Magie", description = "Faszinierend. Es gibt so viele Rätsel in dieser Zitadelle, die niemand, außer Hüter Tyr selbst, versteht. Falls wir das weiter erschließen möchten, müssen wir Tyrhold weiter erkunden.\n\nIch glaube, dass die Schuppe weitere Geheimnisse zutage fördern wird, die an diesem Ort aufbewahrt liegen.\n\nWobei es ein Problem gibt. Die Wächter Tyrholds sind immer noch... instabil. Es ist möglich, dass sie durch Eure Erkundungen gestört werden und versuchen einzuschreiten. Nehmt diese Leitung. Sie wird Euch helfen, falls die Wächter sich als Ärgernis erweisen sollten.", sourceObjective = "Zieht verborgene Magie aus den Konsolen in Tyrhold, um das Geheimnis der Silberschuppe zu enthüllen.", progress = "Was habt Ihr entdeckt?", completion = "Dieser Funke fühlt sich vertraut an! Ich wusste nicht, dass es so etwas hier in Tyrhold gibt. \n\nSehr interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[67076] = { id = 67076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Funken der Entdeckung", description = "Obwohl dieser Funke eigenartig ist, spüre ich, dass er mir bekannt ist. Ich bin mir nicht sicher, was sein Nutzen ist, aber ich glaube, er führt uns einen Schritt näher zur Lösung dieses Rätsels.\n\nFolgt ihm, um herauszufinden, ob Ihr seinen Zweck aufdecken könnt, während ich in der Zwischenzeit versuche, mehr herauszufinden.", sourceObjective = "Untersucht den Titanenfunken in Tyrhold.", completion = "Ich habe eine starke Woge von Magie gespürt, die von Tyrhold ausging... sogar bis nach Valdrakken. Ihre Quelle muss in diesem Funken liegen, den Ihr gefunden habt.\n\nIch frage mich, was das bedeutet...", sourceObjectiveStatus = "unverified-source-field" }
quests[67077] = { id = 67077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen an die Vergangenheit", description = "An diesem Ort sahen wir unseren Freund Tyr zum letzten Mal.\n\nWir verstanden die Beweggründe nicht, warum er uns verlassen musste, außer, dass es wichtig war.\n\nAuch wenn dies unseren Herzen unerträgliches Leid bereitet, denke ich, dass dieser Funke uns gerufen hat, um diesem Zeitpunkt noch einmal beizuwohnen. Mit Nozdormus Hilfe können wir vielleicht diesen Moment erneut durchleben und nachsehen, ob es einen anderen Hinweis gibt, den Tyr uns hinterlassen hat.", sourceObjective = "Sprecht mit Nozdormu und seht die Erinnerung an die Vergangenheit.", progress = "Vergebt mir, {name}. Das ist doch emotional für mich.", completion = "Obwohl diese Erinnerung große Trauer birgt, bin ich doch dankbar, für die Gelegenheit, seine Stimme ein weiteres Mal zu vernehmen... wenn auch nur aus der Vergangenheit.\n\nDanke, dass Ihr uns hergebracht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[67078] = { id = 67078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anweisungen zum Abschied", description = "<Das Echo spricht mit uralter Stimme.>\n\nAn meine lieben Freunde, ich entschuldige mich für meine plötzliche Abreise.\n\nAber ich verspreche, dass Ihr nicht ohne meine Hilfe seid. Ich weiß, dass für Euch die Zeit großer Not gekommen ist, aber um sicherzustellen, dass dieses Geschenk nicht missbraucht wird, muss ich von Euch verlangen, eine Reihe an Aufgaben auszuführen.\n\nDie erste ist einfach: Reaktiviert die Schmiede innerhalb von Tyrhold. Die Silberschuppe ist der Schlüssel.", sourceObjective = "Platziert die Silberschuppe in der Schmiede von Tyrhold.", completion = "Anscheinend ist es doch etwas komplizierter, die Schmiede zu reaktivieren, als man Euch weisgemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[67079] = { id = 67079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüsselmomente", description = "Die Sicherheitsvorkehrungen in der Schmiede sind strenger als in jedem anderen Bereich Tyrholds. Das wird eine ziemliche Herausforderung, {class}.\n\nNur bestimmte Einheiten der Zitadelle können die Sicherheitsmaßnahmen umgehen, und um einer Sicherheitsverletzung vorzubeugen, verlangen die Protokolle stets mehr als einen Code.\n\nDiese Einheiten werden ihre Überbrückungsscheiben nicht freiwillig hergeben, Ihr werdet sie ihnen mit Gewalt abnehmen müssen. Seid vorsichtig, {name}.", sourceObjective = "Beschafft Euch die primäre und die sekundäre Sicherheitsscheibe in Tyrhold.", progress = "Ich hoffe, wir haben Tyrhold nicht wesentlich gestört. Möge der Hüter uns vergeben.", completion = "Hervorragend, {name}. Damit können wir die Anlagen öffnen und die Aufgabe erledigen, die Tyr hinterlassen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[67080] = { id = 67080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Alchemistische Lösung des Drachen", description = "Seid Ihr auf der Suche nach Arbeit, <Alchemist/Alchemistin>?\n\nDas Handwerkerkonsortium ist mit einem \"Handwerksauftrag\" an mich herangetreten. Es besteht Interesse an meinen alchemistischen Lösungen. Diese Geschäftspraktiken klingen zwar interessant, doch ich habe einfach zu viel um die Ohren.\n\nVielleicht ist dies eine Gelegenheit für Euch, Lehrling. Stellt eine alchemistische Lösung her, indem Ihr Eure vorherigen Gemischressourcen zurückgewinnt, und bringt sie zu Haephesta, die sich etwas weiter den Pfad entlang befindet.", sourceObjective = "Verwendet das Rezept 'Gemischressourcen zurückgewinnen' und stellt 2 Flaschen einer alchemistischen Lösung des Drachen für Haephesta beim Rubinlebensschrein her.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[67081] = { id = 67081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Infusion. Eine Infusion der Materialien", description = "<Das Abbild von Tyr spricht erneut.>\n\nIhr habt die Schmiede reaktiviert. Die nächste Aufgabe wird nicht so einfach sein.\n\nIn der Schuppe sind Baupläne geritzt für etwas, das Ihr für mich schmieden sollt. Irideus, einem meiner treuen Hüter, habe ich die nötigen Materialien für diese Aufgabe anvertraut. Es gibt nur noch sehr wenige von ihnen und sie sind unter besonderen Umständen entstanden.\n\nSucht nach Irideus in den Hallen der Infusion. Ich hoffe, dass die Anlage unter seinen wachsamen Augen weiterhin ordnungsgemäß ihrem Betrieb nachgeht.", sourceObjective = "Beschafft Euch 10 uralte Titanenstahlbarren und bezwingt den urtümlichen Tsunami in den Hallen der Infusion.", progress = "Wenn Ihr die erforderlichen Materialien beschafft habt, könnt Ihr Euren Weg fortsetzen.", completion = "Ich nehme an, dass in den Hallen der Infusion alles ordnungsgemäß funktioniert hat und Irideus sich bester Gesundheit erfreut.\n\nUnd nun die nächste Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67084] = { id = 67084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die silberne Bestimmung", description = "<Das Echo von Tyr wird durch Eure Anwesenheit aktiviert.>\n\nEure nächste Aufgabe steht nun bevor, meine Freunde.\n\nVertraut die Barren dem Feuer an und aktiviert die Schmiede. Ich habe die nötigen Abläufe bereits für Euch vorbereitet.\n\nDie Silberschuppe enthält den Bauplan. Sein Nutzen wird sich Euch offenbaren.", sourceObjective = "Platziert die uralten Titanenstahlbarren in der Schmiede und beendet die Aufgabe, die Tyr Euch aufgetragen hat.", completion = "Mir fehlen die Worte, um meine Dankbarkeit Euch gegenüber auszudrücken, {name}! Ihr habt uns einen lange verloren geglaubten Freund zurückgebracht!\n\nUnglücklicherweise hat er uns keine weiteren Anweisungen hinterlassen. Vielleicht finden wir mit der Zeit heraus, wie wir sein wahres Selbst wiederherstellen können.\n\nFalls dies überhaupt möglich ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[67093] = { id = 67093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein anomaler Schrein", description = "Mein Forschungsteam hat ganz in der Nähe ein seltsames Sanktum entdeckt. An dessen Außenseite haben wir Schriftzeichen ausgemacht, Titanenrunen, um genau zu sein. Wir glauben, dass sie auf Aman'thul den Hochvater verweisen, den Anführer der Titanen.\n\nWir wollten das Sanktum genauer untersuchen, haben dabei aber dessen Verteidigung ausgelöst. Ein riesiges Sandamalgam hat uns den Weg versperrt, und wir sind nur ganz knapp mit dem Leben entkommen.\n\nWir sind uns nicht ganz sicher, was es beschützt, aber es muss etwas Wichtiges sein. Könnt Ihr der Sache nachgehen?", sourceObjective = "Findet einen Weg, das verborgene Relikt im Sandverlorenen Sanktum einzusammeln, und kehrt dann zu Nozdormu beim Sitz der Aspekte in Valdrakken zurück.", progress = "Dieses Land ist ein schlafender Riese. Wir sollten ihn mit der nötigen Behutsamkeit wecken.", completion = "<Nozdormu blickt prüfend auf die Sphäre, als Ihr sie ihm überreicht. Der Sand im Inneren leuchtet auf und wirbelt unter seiner Berührung.>\n\nIch hatte gedacht, dies sei in dieser Zeitlinie verloren gegangen. Anscheinend bleibt nichts so, wie es ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[67094] = { id = 67094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Als Dryade hat man immer zu tun", description = "Es ist wunderbar, Valdrakken wieder so lebendig zu sehen. Aber es gibt so viele Dinge, die unter den Tausenden von Jahren der Vernachlässigung gelitten haben, nicht zuletzt all die entzückenden kleinen Tiere in der Stadt! Leider haben wir nicht genug Dryaden, um uns um sie alle zu kümmern.\n\nSagt mal, wie würde es Euch gefallen, zur Ehrendryade von Valdrakken ernannt zu werden? Einige der entzückenden kleinen Freunde der Stadt mussten schon viel zu lange ohne ihre Lieblingsleckerlis auskommen. Wollt Ihr mir nicht helfen, sie zu versorgen?", sourceObjective = "Helft Thalendra, die vielen kleinen Tiere von Valdrakken zu füttern.", progress = "Aber, aber Nachwuchsdryade! Die kleinen Racker können sich ja nicht selbst füttern!\n\nOder... vielleicht schon. Aber wo bliebe denn da der Spaß?", completion = "Oh, wie wundervoll! Ich wette, sie strahlen alle über ihre ganzen kleinen Gesichter, Schnäbel, Schnauzen und was noch alles.\n\nEs gibt aber noch ein kleines Tier, das Eure Hilfe braucht, und ich fürchte, die Lage ist ernst.", sourceObjectiveStatus = "unverified-source-field" }
quests[67095] = { id = 67095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug des Wallenden Walds", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67096] = { id = 67096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug des Wallenden Walds - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67099] = { id = 67099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenaugen", description = "Wir wissen, dass die Djaradin uns direkt angreifen werden, aber es gibt noch andere Gefahren da draußen, die mir Sorgen bereiten. Gefahren, die nicht ganz so offensichtlich sind.\n\nIch habe drei Drachen losgeschickt, welche die Umgebung erkunden und potenzielle Gefahren lokalisieren sollen.\n\nTrefft Euch mit ihnen und sammelt ihre Berichte ein. Kehrt anschließend zu mir zurück, damit wir uns auf das, was die Djaradin geplant haben, bestmöglich vorbereiten können.", sourceObjective = "Sprecht mit Myridian, Zepharion und Evorian in den umliegenden Gebieten.", progress = "Was habt Ihr entdeckt?", completion = "Dank Euch sind wir besser darauf vorbereitet, was die Djaradin uns entgegensetzen wollen.\n\nWir werden unsere Augen stets offen halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[67100] = { id = 67100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Miguel", sourceObjective = "Sprecht mit Thomas über Qualität und sammelt anschließend 3 feurige Geister in der Nähe der Flunkerhöhle für Miguels Geschenk.", progress = "Genau das Richtige für Miguel!", completion = "Fantastisch! Ihr seid so fabelhaft!\n\nHier, nehmt diesen Reagenzienbeutel als Dankeschön. Ihr könnt ihn an der zusätzlichen Stelle Eures Gürtels einhaken. Oh, und solltet Ihr noch mehr Platz brauchen, kann Euch ein begabter Schneider einen noch größeren machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67111] = { id = 67111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kummergeplagte Lehrling", description = "Diese Mission war von Anfang an ein Fehler. Alia Segelstrahl bat uns um Hilfe, um zu verhindern, dass die Splitterflammen in den Besitz eines gefährlichen Artefakts kommen. Wir hatten es in diesen Ruinen ausfindig gemacht.\n\nAber die Splitterflammen haben uns hier besiegt und die Gegend wurde von Eisspinnen überrannt. Alia wurde schwer vergiftet, und ich fürchte, dass sie ohne das Gegenmittel nicht lange überleben wird.\n\nIch kann es herstellen, aber ich brauche dazu Giftdrüsen von den Spinnen in der Nähe. Ich habe Angst, Alia hier zurückzulassen. Könntet Ihr welche für mich finden?", sourceObjective = "Sammelt 5 gefrorene Giftdrüsen.", progress = "Habt Ihr die Giftdrüsen, um die ich gebeten habe?", completion = "Ah, wunderbar! Mit diesen Giftdrüsen kann ich ein Gegengift für Alia brauen. Sie wird sich schon bald wieder besser fühlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67113] = { id = 67113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung in Nöten" }
quests[67137] = { id = 67137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professionelle Ausrüstung", description = "Sagt, ich habe von Haephesta gehört, dass Ihr ebenfalls <ein arbeitender Handwerker/eine arbeitende Handwerkerin> seid.\n\nWir würden Euch gerne kostenlos mit einer Profiausrüstung ausstatten. Dafür sind Geschäftspartner doch da, nicht wahr?\n\nSprecht mit unserer Schneiderin, Mahra Baumbieger, um Maß nehmen zu lassen.", sourceObjective = "Sprecht mit Mahra Baumbieger.", completion = "Hier ist Eure neue Ausrüstung! Probiert sie mal an!\n\nIhr könnt sie über Euren Berufsrezepten ausrüsten.\n\nOh, und wenn Ihr mehr wollt, wendet Euch an andere Handwerker, falls Ihr nicht selbst Ausrüstung herstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[67142] = { id = 67142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wyrmfutter", description = "Für die Obsidianzitadelle zu kämpfen und sie zu beschützen, macht ganz schön hungrig... und wir Drachen können eine ganze Menge essen. Wir müssen unsere Vorräte auffüllen.\n\nUnter der gehärteten Lava lauern einige sehr schmackhafte Würmer, die sich durch das Magma winden! Ihr werdet ihnen vermutlich nicht viel abgewinnen können, doch für einen hungernden Drachen ist das die reinste Delikatesse.\n\nNehmt unseren Diener Gulchak mit und richtet seinen Zeiger auf Unregelmäßigkeiten in der Lava. Er wird die Würmer anlocken, dann müsst Ihr sie nur noch einfangen.", sourceObjective = "Sammelt lavaverkohltes Fleisch von den Krustenlauerern im Glutstrom.", progress = "Habt Ihr etwas Gutes zu essen gefunden?", completion = "<Voraxian stößt in Zustimmung seine Zähne aneinander.>\n\nVielen Dank. Das ist eine große Hilfe dabei, uns wohlgenährt und gesund zu halten. Auf leeren Magen können wir nicht für unsere Zukunft kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67143] = { id = 67143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemandem sein Herz schenken", description = "Denkt Ihr, Ihr könntet die gesammelten Elementaressenzen in diese Flasche geben?\n\nDas Rezept ist ganz einfach, Ihr könnt es genau so verwenden wie jedes andere Rezept.\n\nFalls Euch die hochqualitativen Reagenzien abhandengekommen sind oder Ihr sie aufgebraucht habt, könnt Ihr jederzeit neue von den Elementaren bei der Flunkerhöhle bekommen.", sourceObjective = "Stellt ein Herz in der Flasche |A:Professions-Icon-Quality-Tier3-Small:20:20|a mit einem beliebigen Handwerksberuf her.", progress = "Hallo, kann ich Euch helfen?", completion = "Oh, das ist so süß! Ach, Thomas ist einfach ein Schatz.\n\nSchaut Euch das mal an... Diese herausragende Qualität. Habt Ihr dabei geholfen? Wenn ja, dann vielen Dank. Tausendfach Dank.\n\nUnd richtet auch Thomas meinen herzlichsten Dank aus, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[67154] = { id = 67154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entropische Überreste", description = "Wenn Entitäten die Zeitlinien passieren, kann es passieren, dass sich die Sande der Zeit an ihren Körpern ansammeln.\n\nNormalerweise löst sich der Sand recht schnell wieder, aber manchmal sorgen die entropischen Fluktuationen der Zeitreisen dafür, dass der Sand zu Glas wird. In solchen Fällen lässt er sich nur schwer entfernen. So habe ich mir schon mehrere Paar neue Schuhe ruiniert.\n\nVerglaster Sand hat sich als äußerst wertvoll für unsere Zwecke herausgestellt. Es wäre in unserem besten Interesse, so viel wie möglich davon zu gewinnen.", sourceObjective = "Sammelt 8 Stücke verglasten Sand von Kreaturen in den Wandernden Sanden.", progress = "Wart Ihr erfolgreich? Eigentlich kommt das eher selten vor, aber in letzter Zeit häufiger.", completion = "Eine unerwartet große Ausbeute. Vielleicht verursachen die Risse mehr Probleme, als wir uns ausgemalt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[67167] = { id = 67167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für ein Duell!", description = "Jetzt, wo ich meine Karten zurückhabe, kann ich mich darauf konzentrieren, neue Mitglieder für meinen Club zu rekrutieren! Ich habe daran gedacht, die Dracthyr zu fragen...\n\nOh, da gibt es noch etwas, bei dem Ihr mir helfen könnt, {name}!\n\nIch werde ein bisschen damit beschäftigt sein, andere Drachen zum Mitmachen zu bewegen, und ich möchte unbedingt die Dracthyr dabeihaben.\n\nWürde es Euch etwas ausmachen, für mich mit ihnen zu sprechen? Aber seid gewarnt: Viele von ihnen haben noch nie gespielt.", sourceObjective = "Fordert 8 Dracthyr zu einem Hearthstone-Spiel heraus.", progress = "Wie läuft die Rekrutierung?", completion = "Wunderbar! Vielen Dank für all die Hilfe, {name}! Bei dem neuen Interesse an Hearthstone werden wir sicher die Genehmigung für den Club bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67173] = { id = 67173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Gnolle" }
quests[67174] = { id = 67174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Aufdeckung", description = "Seid gegrüßt! Ich bin Miva Sternauge und ich leite die arkanen Untersuchungen in diesem Gebiet.\n\nDas azurblaue Gebirge ist überall von Magie erfüllt. Teile davon sind harmlos... während andere wiederum recht gefährlich sein können.\n\nMir wurde aufgetragen, sicherzustellen, dass in den Besitztümern der Tuskarr keine arkane Energie zurückbleibt.\n\nWir hatten schon einen Vorfall im Lager Antonidas, bei dem eine Angelkiste spontan in Flammen aufgegangen ist!\n\nKönntet Ihr meinen Detektor nehmen und einige Objekte hier untersuchen? Ich muss noch etwas mit Julk dort drüben besprechen.", sourceObjective = "Untersucht Tuskarrobjekte bei Khuris Angelplatz auf Anzeichen für arkane Magie.", progress = "Hoffen wir, dass hier alles in Ordnung ist.", completion = "Ein Spielzeugboot, das gleichzeitig eine magische Zeitbombe ist?\n\nOh, Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[67175] = { id = 67175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Spielzeugboot vom Explodieren abhält", description = "Ich bringe ein Kind nur ungern um sein Spielzeug, aber es würde sich für die Kirin Tor als äußerst wertvoll erweisen, zu untersuchen, wie es so viel Arkana absorbieren konnte.\n\nAndererseits möchte ich unsere neuen Verbündeten von den Tuskarr auch nicht kränken. Ich besitze einen Zauberstab, der die Magie entfernen könnte...\n\nSprechen wir zuerst mit Toolks Mutter und entscheiden dann über das weitere Vorgehen.", sourceObjective = "Sprecht mit Toolks Mutter und holt dann das Spielzeugboot.", progress = "Der Zauberstab sollte etwaiges Entzaubern übernehmen, wenn wir nicht zu spät sind.", completion = "Wir haben heute das Richtige getan. Es gibt da draußen noch viele andere magische Rätsel zu entdecken, aber dieses Mädchen wird kein weiteres Geschenk von ihrem verlorenen Vater bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67177] = { id = 67177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Verschlinger", description = "Wenn Ihr Euch in den Reihen der Tuskarr aufhalten wollt, solltet Ihr Euch nützlich machen!\n\nIn letzter Zeit hat sich in der Nähe ein wildes Tier eingenistet, das wir Verschlinger nennen.\n\nNoch mehr seiner Art scheinen in diese Gegend zu migrieren. Das können wir zu unserem Vorteil nutzen.\n\nTötet den Verschlinger und bringt mir seine Hörner. Wir werden sie nutzen, um unseren Außenposten zu erweitern.", sourceObjective = "Tötet den Verschlinger und besorgt seine Hörner.", progress = "Habt Ihr die Hörner?", completion = "Gute Arbeit! Das werden wir für unsere zukünftigen Ausbaupläne zur Seite legen.\n\nEs ist bedenklich, dass der Verschlinger und seine Artgenossen hierher migriert sind, aber wir werden das Beste daraus machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67178] = { id = 67178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiße Augen, blauer Drache", sourceObjective = "Helft Yumodormu, Setogosa zu besiegen", completion = "Danke für Eure Hilfe! Ohne Euch hätte ich Setogosa sicher nicht besiegt.\n\nSetogosa geht es gut, ich warte nur darauf, dass sie sich etwas beruhigt, bevor ich die Umkehrung umkehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[67221] = { id = 67221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Köpfchen für Metall", description = "Um das Potenzial der Schmiede des Erdwächters voll auszuschöpfen, müsst Ihr die Grundlagen zur Herstellung obsidianversengter Legierung erlernen. Nur dann könnt Ihr in die Fußstapfen von Neltharions größten Schmieden treten.\n\nBringt mir ein Stück kristallisiertes Drakonium, das sich tief in der Aschenscherbenspalte finden lässt. Im Gegenzug werde ich Euch das Wissen vermitteln, nach dem Ihr sucht.", sourceObjective = "Sammelt 1 Stücke kristallisiertes Drakonium in der Aschenscherbenspalte.", progress = "Habt Ihr gesammelt, was ich brauche?", completion = "Eure Erfolge haben Euch dieses Wissen eingebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[67222] = { id = 67222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdunkelte Wolken", description = "Die Primalisten haben die Windspielanhöhe mit ihren unsinnigen Lehren infiziert. Unsere Verwandten dort sind närrisch, diese Ideen zu dulden.\n\nWenn wir dabei helfen, diesen heiligen Boden von ihrer Anwesenheit zu befreien, werden die anderen Klans uns vielleicht unterstützen, wenn es nötig wird. Glaubt Ihr, Ihr könntet helfen?", sourceObjective = "Vertreibt die Primalisten von der Windspielanhöhe.", completion = "Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[67295] = { id = 67295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist meine Spezialität", description = "So so, Ihr habt Euch also einer Spezialisierung gewidmet, ja? Wunderbare Sache das, wenn man sich eine exklusive Fertigkeit angeeignet hat.\n\nAls Mitglied des Handwerkerkonsortiums wäre es mir eine Ehre, Euch dabei zu helfen, Eure Künste zu verfeinern.\n\nVielleicht habt Ihr ja einen Moment Zeit, um Euch mein Wissen anzuhören oder etwas zu lernen, das Euch auf Euren Abenteuern hilft?", sourceObjective = "Sprecht mit Miguel Heller über eine Berufsspezialisierung.", completion = "Ausgezeichnet. Solltet Ihr je irgendwelche Fragen zu Spezialisierungen haben, könnt ihr mich jederzeit noch mal darauf ansprechen.\n\nUnd nun geht und übt Euch weiter in Euren Talenten! Oh, und nehmt das hier mit. Ich habe es auf meinen Reisen gefunden.\n\nEs hat etwas Geheimnisvolles an sich. Vielleicht kann das Wissen, das in ihm ruht, Euch bei Eurer Spezialisierung helfen.\n\nThomas meinte, er hätte vor Kurzem einen Meisterhandwerker getroffen. Möglicherweise kann dieser Meister Euch dabei behilflich sein, die Geheimnisse dieses Dings zu lüften?", sourceObjectiveStatus = "unverified-source-field" }
quests[67296] = { id = 67296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iskaara-Tour", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67297] = { id = 67297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iskaara-Tour - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67298] = { id = 67298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wunder der Welt", description = "Mein Mann Thomas hat durch seine Erkundungen dieses urzeitlichen Landes viele Einsichten gewonnen.\n\nVielleicht würdet Ihr eine ähnliche Inspiration erfahren, wenn Ihr in seine Fußstapfen tretet?", sourceObjective = "Findet heraus, wie Thomas seine handwerklichen Einsichten erhält.", progress = "Ich könnte ewig hier entspannen.", completion = "Interessant, in der Tat! Man kann wahrlich nie wissen, wo sich Wissen auftut.\n\nHaltet die Augen nach ähnlichen Schätzen offen, vielleicht hält die Welt noch mehr Weisheit für Euch bereit.\n\nUnd habt Dank, dass Ihr diesen Ausblick mit mir genossen habt. Ist er nicht spektakulär?", sourceObjectiveStatus = "unverified-source-field" }
quests[67299] = { id = 67299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg mit den Drachen", description = "Die Primalisten haben unser Lager ohne Unterlass mit ihren Drachen angegriffen!\n\nWir konnten sie dank unserer Schilde zurückhalten, aber wir könnten etwas Hilfe dabei brauchen, sie aus der Luft zu holen.\n\nNutzt einen unserer Strahler, um die Drachen auszuschalten!", sourceObjective = "Nutzt einen Arkanstrahler, um 5 Protodrachen zu töten.", completion = "Ich danke Euch. Jede Verschnaufpause, die wir uns von diesen Angriffen verschaffen können, ist willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67564] = { id = 67564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerpost", description = "<Abenteurer/Abenteurerin>, seid Ihr auf dem Weg zum Lebensschrein?\n\nWürde es Euch etwas ausmachen, Thomas Heller diese Rechnung vorbeizubringen? Er hat ein paar handgefertigte Flaschen bestellt und unser Glasbläser hat endlich die Kosten für die benötigten Materialien.\n\nIhr solltet ihn den Weg hier weiter runter finden. Wahrscheinlich sülzt er gerade irgendeine arme Seele damit voll, wie toll sein Gatte ist...\n\nIch bin mir sicher, dass er Euch für Eure Zeit entlohnen wird.", sourceObjective = "Händigt die Rechnung des Handwerkerkonsortiums an Thomas Heller aus.\n\nBereitgestellter Gegenstand:", completion = "Oh, ausgezeichnet! Das wollte ich sowieso bei Haephesta abholen. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[67565] = { id = 67565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostland-Überflug", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67566] = { id = 67566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostland-Überflug - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67605] = { id = 67605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnernde Ebenen", description = "Auf dem Grat wandert eine große Sturmbestie. Viele Jäger der Shikaar haben versucht, sie zu erlegen, nur um vor seiner Wildheit zu fallen.\n\nWenn es Euch nach Jagdruhm dürstet, könnt Ihr gern versuchen, die Bestie zu erschlagen. Bringt uns ihr Horn als Tribut.", sourceObjective = "Erringt Ayangas Horn.", progress = "Und, habt Ihr die Bestie gesehen?", completion = "Ausgezeichnete Arbeit. Die nächste Generation unserer Jäger wird Eure Geschichte hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[67606] = { id = 67606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dryadenhausmittel", description = "Während Ihr fort wart, habe ich von einem Traumhasen gehört, dass eines der hiesigen Entchen sich nicht wohl fühlt. Zum Glück weiß ich genau, was man dagegen tun kann!\n\nWann immer ich schlecht gelaunt bin, nasche ich etwas Süßes! Als Expertin für niedliche, liebenswürdige Kreaturen weiß ich, dass das in diesem Fall auch funktionieren wird.\n\nDieses besondere Entchen hat eine Vorliebe für ein Dessert namens schmackhafter Schlüpflingschmaus. Würdet Ihr bitte eines finden und dem armen Schätzchen bringen? Immerhin ist das die dryadische Art!", sourceObjective = "Beschafft einen schmackhaften Schlüpflingschmaus und gebt ihn dem verzweifelten Entchen.", progress = "Also, wie geht es unserem leidenden Vögelchen?", completion = "Oh, vielen Dank, {name}! Wir Dryaden haben so viel zu tun, dass es schwierig sein kann, nach jedem kleinen Vögelchen oder Tier zu sehen, das sich auf diesen Straßen umhertreibt.\n\nMit Eurer Hilfe aber hat sich alles zum Besten gewendet! Ihr habt Euch als nützliche Aushilfsdryade erwiesen! Vielleicht werde ich Euch in der Zukunft noch einmal um Eure Hilfe ersuchen. Es gibt immer noch weitere bezaubernde kleine Tierchen, um die man sich kümmern kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[67700] = { id = 67700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Dracheninseln!", sourceObjective = "Nehmt die Abgewetzte Drachenschuppe vom Hafen von Sturmwind zu den Dracheninseln.", completion = "Willkommen auf den Dracheninseln!", sourceObjectiveStatus = "unverified-source-field" }
quests[67717] = { id = 67717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespinstkönigin Ashkaz" }
quests[67722] = { id = 67722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Durchbruch", description = "Toddy und Naleidea bereiten sich zum Aufbruch vor. Trefft sie bei der versiegelten Titaneneinrichtung in Thaldraszus. Offenbar hatten sie einen Durchbruch.\n\nBringt auf jeden Fall alle relevanten Informationen mit, damit ich sie katalogisieren kann!", sourceObjective = "Trefft Toddy und Naleidea außerhalb der versiegelten Titaneneinrichtung in Thaldraszus.", completion = "Ihr habt es geschafft! Und gerade rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[67724] = { id = 67724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schützende Flammen", description = "Kattigat und ich sind hierhergekommen, um uns zu beweisen, indem wir die Splitterflammen aufhalten und Valthrux sichern.\n\nUnd jetzt müssen wir auf diese Elfe aufpassen, nachdem sie ein paar Eisspinnenbisse abbekommen hat. Wir haben noch nicht einmal gegen die Splitterflammen gekämpft, und die Spinnen könnten uns erledigen, bevor es überhaupt dazu kommt!\n\nWir müssen sie in Schach halten.\n\nGlücklicherweise gibt es eine natürliche Methode, die Spinnen zu vertreiben. Wenn man die Seide ihrer Kokons verbrennt, entsteht ein Geruch, der sie abschreckt.\n\nGreift Euch etwas Seide und ich werfe sie dann ins Feuer. Das wird sie abhalten!", sourceObjective = "Sammelt 4 Stücke Schaudernetzseide.", progress = "Konntet Ihr Spinnenseide auftreiben?", completion = "Sehr gut! Diese Spinnenseide wird lange brennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[67741] = { id = 67741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivring", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67742] = { id = 67742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivring - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[67744] = { id = 67744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shezra" }
quests[67772] = { id = 67772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Problem mit Taivan", description = "Hallo, willkommen zurück in Maruukai. Ich bin Selbekh, Heilerin des Klans Teerai.\n\nHabt Ihr ein Händchen für Tiere, {name}? Vielleicht ist der Einfluss eines Neulings genau das, was ich brauche.\n\nTaivan hier, wenn auch ein besonders guter Begleiter, ist zu einer Art Last für meinen Klan geworden. Ich fürchte, dass ich ihn wegschicken muss, wenn wir keinen guten Nutzen für ihn finden. Würdet Ihr mir helfen?", sourceObjective = "Helft Heilerin Selbekh, Taivan für die Ausbildung vorzubereiten.", completion = "Was führt Euch in die Jagdgründe der Shikaar, Fremdling?\n\nDie Teerai wollen ihren Bakar von uns zum Jagdtier ausbilden lassen? Wir nehmen normalerweise keine Anfragen von anderen Klans an, aber ich werde darüber nachdenken. Ihr Geschenk ist äußerst großzügig und ein voll ausgebildetes Tier seiner Größe wäre ein beeindruckender Anblick. Ich wette, er könnte einen Mammutbullen ganz allein erlegen!\n\nHmm... Ich muss ihn in Aktion sehen, bevor ich eine Entscheidung treffen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[67921] = { id = 67921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jagdhund", description = "Geht und jagt in der Nähe Tiere mit Eurem riesigen Bakar. Je größer, umso besser. Ich werde Euch von hier aus beobachten und entscheiden, ob er einer Shikaarausbildung würdig ist.\n\nSeid gewarnt, ich akzeptiere nur die Besten.", sourceObjective = "Jagt gefährliche Wildtiere mit Taivan, um zu beweisen, dass er würdig ist, ausgebildet zu werden.", progress = "Geht und jagt in der Nähe Tiere mit Eurem Bakar. Ich werde zusehen.", completion = "Euer Bakar mag riesig und stark sein, aber ihm fehlt der Wille für das, was auf der Jagd getan werden muss. Er ist zu weich!\n\nIch gebe ihm eine letzte Chance, aber mehr auch nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[68083] = { id = 68083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nächster Versuch, Taivan!", description = "Kehrt zu den Teerai zurück und sagt ihnen, dass nicht einmal ich Taivan zu einem Jagdbakar ausbilden kann. Er ist einfach nicht dafür gemacht.\n\nEr ist das handzahmste Tier, das ich je gesehen habe. Ich wette, er würde sogar noch versuchen, sich mit dem Jagdwild anzufreunden, wenn man ihn ließe. Ha!", sourceObjective = "Kehrt zu Heilerin Selbekh in Maruukai zurück und überbringt ihr die schlechte Nachricht.", completion = "Taivan ist gerade angekommen. Sie können ihn nicht so schnell ausgebildet haben, oder? Nein... ich schätze nicht.\n\n<Sie seufzt schwer und sieht zu Taivan.>\n\nEr scheint es auch nicht gut aufzufassen. Ich habe noch eine letzte Idee. Wenn die nicht funktioniert, werden wir einige schwierige Entscheidungen treffen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[68084] = { id = 68084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ruhige Riese", description = "Wenn Taivan wirklich so \"handzahm\" ist, wie Jadar sagt, ist er vielleicht besser als Hütebakar geeignet!\n\nDie Aylaag sind meisterhafte Riesenwildschäfer und nicht so stolz, dass sie überschwängliche Geschenke brauchen, um einem anderen Klan zu helfen.\n\nBringt Taivan bitte zu Schäfer Tevatei im Mallakh, einem Ort zwischen zwei Hügeln im Südwesten, wo sie ihre Bakar ausbilden.\n\nOhn'ahra, bitte macht, dass das funktioniert. Sonst weiß ich nicht mehr weiter.", sourceObjective = "Bringt Taivan zu Schäfer Tevatei im Mallakh, um dort ausgebildet zu werden.", completion = "Aber hallo, Neuling. Was kann ich für Euch und Euren sehr großen Freund tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[68085] = { id = 68085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werdegang eines Hirten", description = "Ihr wollt, dass ich Euren Bakar im Schafehüten ausbilde? Das ist es jedenfalls, was wir hier tun, doch ich habe noch nie einen Bakar von solcher STATUR ausgebildet...\n\nDie Riesenwildschafe scheinen sich immerhin nicht an seiner Anwesenheit zu stören und sie besitzen ein gutes Gespür für den Charakter, das könnt Ihr mir glauben.\n\nIch bin bereit, ihm einen Versuch zu geben, aber ein Hütebakar muss nicht nur sanft sein, sondern auch klug. Wenn er nicht die Kontrolle über die Herde gewinnen kann, werden die Riesenwildschafe ihm auch nicht gehorchen. Es ist schwieriger, als es aussieht! Los, versucht es, ich werde zusehen.", sourceObjective = "Bringt Taivan im Mallakh bei, Riesenwildschafe zu hüten.", progress = "Versucht, Taivan zu befehlen, die Herde Riesenwildschafe zu hüten. Ich werde schnell erkennen, ob er eine Begabung dafür besitzt oder nicht.", completion = "Hmm... Taivan wirkt immer noch verwirrt. Er scheint es einfach nicht zu begreifen.\n\nIhr hingegen habt hervorragende Arbeit geleistet! Ihr wärt nicht zufälligerweise an einem Karrierewechsel interessiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[68087] = { id = 68087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr in Daruukhan", description = "Ich fürchte, ich kann nichts weiter tun, als Euch und Taivan nach Maruukai zurückzuschicken.\n\nWartet... Wer kommt da? Hoffentlich nicht noch ein Fremder mit einem riesigen Bakar!", sourceObjective = "Sprecht mit dem Boten der Teerai, um von Selbekhs dringender Bitte zu erfahren.", completion = "Oh, {name}! Ohn'ahra sei Dank, der Bote hat Euch gefunden. Wir haben hier alle Hände voll zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[68639] = { id = 68639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisbären auf der Jagd", description = "Die Spezies, die wir untersuchen sollen, sind die Kaltpelze.\n\nIhr Jagdrevier wurde von den Leylinien verunreinigt. Arkane Energie breitet sich im Wasser und in den Pflanzen aus... und in Beutetieren wie den Slyvern.\n\nDoch im Gegensatz zu anderen Organismen, überleben die Kaltpelze den Prozess und schöpfen daraus sogar Kraft.\n\nAllerdings werden sie dadurch auch aggressiv... was wiederum ein Problem darstellt. Legt Euch mit ein paar von ihnen an, damit ich Aufzeichnungen zu ihrer Stärke und Aggressivität machen kann.\n\nMein Bericht wird den Kirin Tor bei der Entscheidung helfen, wie mit ihnen weiter vorzugehen ist.", sourceObjective = "Tötet 6 infizierte Kaltpelze.", completion = "<Sie kritzelt Anmerkungen in ihr Notizbuch.>\n\nJa... Ja, das ist alles sehr hilfreich. Hoffentlich können die Kirin Tor diese Informationen verwenden, um anderen zu helfen, die von der arkanen Krankheit betroffen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[68640] = { id = 68640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plötzliche Isolation", description = "Früher haben wir regelmäßig mit dem Uktulutstamm an der Küste des Erwachens gehandelt, aber seit Monaten haben sie keine Lieferungen mehr geschickt oder angenommen. Unsere Briefe sind unbeantwortet geblieben. Deshalb befürchten wir das Schlimmste.\n\nIhr Häuptling Tutaqan war stets von der vernünftigen Sorte. Etwas emotional veranlagt, ja, aber ich kann mir nicht vorstellen, dass es unter seiner Führung zu Vorfällen gekommen sein kann.\n\nWürdet Ihr nach dem Rechten sehen? Wenn sie Hilfe brauchen, sind wir gerne für sie da.", sourceObjective = "Versucht, Kontakt zu den Tuskarr von Uktulut herzustellen.", completion = "Ihr wollt nach uns sehen? Sehr glaubwürdig.", sourceObjectiveStatus = "unverified-source-field" }
quests[68641] = { id = 68641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Moos nix los", description = "Armes Kleines...\n\nSie muss krank geworden sein, nachdem sie etwas Verunreinigtes gegessen hat.\n\nZum Glück war mein Großvater Druide und hat mir beigebracht, wie man arkan hervorgerufene Krankheiten behandelt.\n\nIch habe nicht alles Nötige bei mir, doch in der Umgebung sollte sich was finden lassen.\n\nZuerst brauche ich etwas Drakmoos. Das ist eine seltene Flechtenart, die nur auf Drachenknochen wächst.", sourceObjective = "Sammelt 5 Drakmoosklumpen.", progress = "Habt Ihr das Moos gesammelt?", completion = "Oh! Vielen Dank, {name}!\n\nIch bin zwar Magierin, aber manchmal sind natürliche Lösungen am effektivsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[68642] = { id = 68642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeit nadelt", description = "Ich will Sylvie helfen, aber ich will Calli auch nicht länger warten lassen.\n\nUm Sylvie die Medizin zu verabreichen, brauche ich arkanerfüllte Federkiele von den Kristallrücken. Die werden sicherlich nichts dagegen haben, wenn Ihr ihnen ein paar davon ausrupft.\n\nUnd passt auf die Bakar auf! Sie fressen Kristallrücken und werden es nicht gerne sehen, wenn ihr sie anfasst. Wenn es also hart auf hart kommt und Ihr Euch verteidigen müsst, lässt sich bei ihnen auch der ein oder andere Federkiel finden.\n\nAber... versucht es bitte nicht, darauf ankommen zu lassen.", sourceObjective = "Sammelt 15 arkanerfüllte Federkiele.", progress = "Passt mit den Federkielen auf! Die sind SEHR spitz. Dreimal dürft Ihr raten, woher ich das weiß!\n\n<Steria seufzt.>", completion = "Habt Dank, {name}. Ihr habt Euch doch nicht an den Kristallrücken verletzt, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[68643] = { id = 68643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vitamine und Mineralien", description = "Ich hätte eigentlich damit rechnen können, dass es Steria nicht gefallen würde, wenn ich Euch darum bitte, Tiere zu bekämpfen...\n\nSelbstverständlich gibt es alternative Forschungsmethoden.\n\nNehmt diese Phiolen und sammelt etwas Wasser von den Eiskristallen in der Nähe.\n\nMeine Theorie ist, dass sie Mineralien beinhalten, die mit der Energie von Leykristallen angereichert sind... was wiederum die Ursache für den Ausbruch hier sein könnte.", sourceObjective = "Sammelt 4 mineralerfüllte Wasserphiolen.", progress = "Habt Ihr alle Phiolen gefüllt?", completion = "Ausgezeichnet, {name}.\n\nDiese Proben sollten uns ein besseres Bild davon geben, wie der Ausbruch sich verbreitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[68644] = { id = 68644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süß wie Zucker", description = "Na bitte! Jetzt habe ich alles, was ich für Sylvie brauche!\n\nUnd genau zur richtigen Zeit. Ich bezweifle, dass sie noch viel länger durchgehalten hätte.\n\nAllerdings... brauche ich jemanden, der mir hilft. Ich würde ja Calli fragen, aber... würdet Ihr mir vielleicht noch mal helfen?\n\nGebt mir Bescheid, sobald Ihr bereit seid, {name}.", sourceObjective = "Helft bei der Behandlung von Sylvie.", completion = "Ich habe sie geheilt, aber sie ist nach wie vor ganz klar aufgebracht.\n\nHm, ich frage mich, ob...", sourceObjectiveStatus = "unverified-source-field" }
quests[68794] = { id = 68794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenbund", description = "Dass Ihr den Dracheninseln geholfen habt, ist nicht unbemerkt geblieben, {name}.\n\nDie Lebensbinderin höchstpersönlich möchte Euch als Belohnung für die Dienste, die Ihr den Drachen erwiesen habt, etwas zeigen.\n\nBesteigt die Turmspitze und sprecht mit ihr. Alle Aspekte erwarten Euch.", sourceObjective = "Sprecht mit Alexstrasza am Sitz der Aspekte in Valdrakken.", completion = "Vielen Dank, dass Ihr gekommen seid, {name}. Wir möchten Euch etwas zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[68795] = { id = 68795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiten", description = "Euch ist vermutlich bereits aufgefallen, dass die Dracheninseln sehr weitläufig sind.\n\nEinige der Drachen haben ein flammendes Interesse daran, in diesem erneuerten Land jede Ecke zu erkunden und jedes Geheimnis aufzudecken, auch wenn man es nicht vom Boden aus erreichen kann. Sie freuen sich über ein zweites Paar Augen, das ihnen auf ihrer Reise hilft und werden im Tausch gerne einen Reiter über das Land tragen.\n\nSprecht mit Lord Andestrasz hier im Rubinlebensschrein. Er wird Euch erklären, was sie vorhaben.", sourceObjective = "Sprecht mit Lord Andestrasz im Rubinlebensschrein.", progress = "Mit der Zeit kommt die Übung.", completion = "Lasst uns anfangen.\n\nKeine Sorge, die aufregenden Manöver kommen erst später.", sourceObjectiveStatus = "unverified-source-field" }
quests[68796] = { id = 68796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Himmelhochobservatorium", description = "Das sind die Grundlagen im Drachenreiten! Ihr macht das ziemlich gut.\n\nJetzt würde ich Euch gerne den anderen vorstellen, die auch in dieses Abenteuer verwickelt sind. Wir haben uns drüben im Himmelhochobservatorium eingerichtet.\n\nCelormu kann Euch dorthin führen. Sprecht mit ihm, wenn Ihr Euch für den Flug bereit fühlt!\n\nWir sehen uns dann dort!", sourceObjective = "Reist zum Himmelhochobservatorium an der Küste des Erwachens.", progress = "Seid Ihr bereit für ein Abenteuer?", completion = "Ich war so erpicht darauf, Euch unser Fundament hier zu zeigen, dass ich wohl etwas zu schnell geflogen bin. Tut mir leid!\n\nEs gibt momentan noch nicht viel zu sehen, weil es so lang her ist, dass jemand auf diesen Terrassen gewohnt hat. Nichtsdestotrotz werden wir sie wieder zu unserem Zuhause machen.\n\nNun, stellen wir Euch den anderen vor!", sourceObjectiveStatus = "unverified-source-field" }
quests[68797] = { id = 68797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Paar Hörner", description = "Wie auch den Sterblichen ist den Drachen ihr Äußeres sehr wichtig. Euer Drache kann sein Aussehen ebenfalls verändern, je nachdem, was Ihr findet und erlebt.\n\nSprecht mit Glensera am Podium der Transformation und seht selbst!", sourceObjective = "Trefft Glensera und verwendet das Podium der Transformation, um das Aussehen Eures Drachen zu verändern.", progress = "Manchmal frage ich mich, ob mir rote Haare stehen würden. Was meint Ihr?", completion = "Bei Euren Erkundungsgängen über die Dracheninseln werdet Ihr auf viele weitere individuelle Erscheinungsbilder für Euren Reitdrachengefährten stoßen.\n\nIhr sollt beide stets geschmackvoll herausgeputzt reisen! Und das sollte man auch sein, wenn man neue Lande durchstreift. Der erste Eindruck zählt, vergesst das nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[68798] = { id = 68798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsreitentalente und Ihr", description = "Natürlich sind nicht nur Glensera und ich an diesen Abenteurern interessiert. Lithragosa freut sich auch darauf, Euer Geschick im Drachenreiten zu verbessern, und Celormu habt Ihr glücklicherweise bereits getroffen.\n\nAls Nächstes solltet Ihr mit Lithragosa sprechen. Sie kann Euch zeigen, welche Fertigkeiten Ihr noch lernen könnt!", sourceObjective = "Sprecht mit Lithragosa, um Eure Himmelsreitenfertigkeiten zu sehen.", progress = "Habt Ihr die Drachenglyphe gefunden?", completion = "Wie Ihr sehen könnt, sind wir alle aus den verschiedenen Drachenschwärmen zusammengekommen, um unseren Drachen und Euch zu helfen. Wir alle wollen Abenteuer erleben!\n\nNatürlich konnten wir bisher noch kein Mitglied des schwarzen Drachenschwarms überzeugen, sich uns anzuschließen. Die Brüder und Schwestern sind schwer aufzutreiben! Aber das könnte sich eines Tages ändern...", sourceObjectiveStatus = "unverified-source-field" }
quests[68799] = { id = 68799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Rubinlebensschrein", description = "Und dies ist nur der Anfang Eurer Reise auf dem Rücken eines Drachen!\n\nHaltet die Augen stets nach neuen Abenteuern und Erfahrungen offen und besucht uns in unseren Außenposten, die überall auf den Dracheninseln verteilt sind.\n\nDoch kehrt nun fürs Erste zu Alexstrasza zurück und setzt Eure Erkundungen dieser Lande fort.", sourceObjective = "Kehrt zum Rubinlebensschrein zurück.", completion = "Willkommen zurück.\n\nEs gibt noch viel zu tun, doch Ihr solltet wissen, dass Ihr Euch nicht allein in die Lüfte schwingt.", sourceObjectiveStatus = "unverified-source-field" }
quests[68863] = { id = 68863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verlorener Stamm", description = "Hallo, {name}!\n\nMurik in Iskaara wollte mit Euch über etwas sehr Wichtiges sprechen. Ihr solltet Euch das anhören.", sourceObjective = "Sprecht mit Murik in Iskaara.", completion = "Ich wäre Euch für Eure Hilfe sehr dankbar, {name}, falls Ihr einen Moment Zeit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[69093] = { id = 69093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Mysterium", description = "<Dok Charly ist außer Atem, als er Euch einen Brief überreicht, der Euch zurück ins Basislager der Drachenschuppenexpedition einlädt. Er versucht, das Anliegen eifrig zu erklären.>\n\nVersiegelte Tür. Titanengeheimnisse. Ja?\n\n<Dok Charly nickt aufgeregt, während er auf Eure Antwort wartet.>", sourceObjective = "Sprecht mit Naleidea Flussglanz im Drachenschuppenbasislager.", completion = "Könnte ich Euch für die Geschichte einer mysteriösen versiegelten Tür begeistern?", sourceObjectiveStatus = "unverified-source-field" }
quests[69094] = { id = 69094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zentauren retten", description = "Die Heimtücke der Nokhud kennt keine Grenzen! Lediglich Handwerker leben in Daruukhan. Sie hatten absolut keine Chance gegen die Räuber.\n\nWir brauchen dringend Eure Hilfe, {name}. Die Nokhud sind noch in der Nähe, und wir müssen die Verwundeten versorgen!\n\nDurchsucht das Dorf und bringt die Überlebenden zu mir. Wir kümmern uns dann um sie und stabilisieren sie, so gut es geht!", sourceObjective = "Rettet verwundete Zentauren in Daruukhan.", progress = "Wir werden hier überrannt! Bitte, rettet so viele, wie Ihr könnt!", completion = "Das... das sollten alle sein!\n\nTaivan! Das war unglaublich! Ich hätte nicht gedacht, dass so etwas in ihm steckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[69095] = { id = 69095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimwärts mit Hund", description = "Dank Euch und Taivan sind alle stabilisiert, doch viele der Dorfbewohner müssen noch etwas in Maruukai bleiben, um sich zu erholen.\n\nWarum führt Ihr beiden nicht gemeinsam den Zug zurück? Ihr seid schließlich die Helden der Stunde!", sourceObjective = "Reitet mit Taivan zurück nach Maruukai.", progress = "Wir sind bereit aufzubrechen. Steigt auf Taivan auf, sobald Ihr bereit seid.", completion = "Da wären wir, gesund und munter zu Hause.\n\nIch kann nicht in Worte fassen, wie froh ich war, als Ihr und Taivan ankamt. Ihr habt heute viele Leben gerettet!", sourceObjectiveStatus = "unverified-source-field" }
quests[69096] = { id = 69096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taivans Bestimmung", description = "Seht Ihr das Zentaurenkind, das ganz alleine da drüben am Bachufer sitzt?\n\n<Sie deutet nach Nordosten, wo Ihr ein Zentaurenkind aufs Wasser starren seht.>\n\nChimei hat während des Angriffs der Nokhud beide Eltern verloren. Alle körperlichen Wunden konnte ich heilen, doch ich habe Chimei bisher noch nicht essen sehen oder sprechen hören. Sitzen und starren, den ganzen Tag.\n\nDas übersteigt meine Fähigkeiten und ich weiß nicht, was ich tun soll. Könntet Ihr versuchen, mit Chimei zu sprechen, {name}?", sourceObjective = "Versucht, die Zentaurenwaise Chimei zu trösten.", progress = "Wie sieht es aus?", completion = "<Selbekhs Augen sind noch ganz feucht.>\n\nTaivan... Das ist also seine wahre Gabe.\n\nWie konnte ich nur so blind sein? Ja, er ist anders als die anderen Bakar, aber er hat sich als wertvolles Mitglied von Klan Teerai bewiesen. Er wird bis ans Ende seiner Tage an meiner Seite bleiben und retten, wen er kann, und heilen, wen ich nicht heilen kann.\n\nBitte, kommt uns jederzeit besuchen! Wir beide sind für alles, was Ihr für uns getan habt, unendlich dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[69097] = { id = 69097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unversiegelte Kammer", description = "<Dok Charly ist außer Atem, als er Euch einen Brief überreicht, der Euch zurück ins Basislager der Drachenschuppenexpedition einlädt. Er versucht, das Anliegen eifrig zu erklären.>\n\nLauter Zwerg. Ernster Elf. Bereit für Euch. Ja?\n\n<Dok Charly nickt aufgeregt, während er auf Eure Antwort wartet.>", sourceObjective = "Sprecht mit Katalogisiererin Jakes im Drachenschuppenbasislager.", completion = "Es tut gut, Toddy und Naleidea wieder hier zu haben. Wenn ich nur endlich etwas Ruhe in meinem Zelt haben könnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[69667] = { id = 69667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dampfkieme" }
quests[69668] = { id = 69668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmokflunk der Feuerspeier" }
quests[69837] = { id = 69837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenschuppenungetüm" }
