quests[69854] = { id = 69854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solethus' Grabstein" }
quests[69855] = { id = 69855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berufung zum Klettern", description = "<Dok Charly ist außer Atem, als er Euch einen Brief überreicht, der Euch für weiteres Training zurück ins Basislager der Drachenschuppenexpedition einlädt. Er versucht, das Anliegen eifrig zu erklären.>\n\nVon großer Jeb. Guter Freund. Jetzt klettern. Ja?\n\n<Dok Charly nickt aufgeregt, während er auf Eure Antwort wartet.>", sourceObjective = "Sprecht mit Pfadfinder Jeb im Drachenschuppenbasislager.", completion = "Ihr seht aus, als wärt Ihr stark, aber ich frage mich, ob Ihr den nötigen Schneid habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[69856] = { id = 69856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fulgurb" }
