quests[69861] = { id = 69861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trilvarus Lehrenweber" }
quests[69862] = { id = 69862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slyvernrettung", description = "Jetzt, wo sie geheilt ist, will Sylvie uns, glaube ich, etwas zeigen.\n\nUnsere Arbeit ist noch nicht getan, {name}! Sehen wir mal nach, weswegen sie so aufgeregt ist.", sourceObjective = "Findet heraus, weswegen Sylvie so aufgeregt ist.", completion = "Es ist ganz leise, doch das klingt so, als wären da Junge in der Höhle!\n\nDas ist gar nicht gut...", sourceObjectiveStatus = "unverified-source-field" }
