quests[69869] = { id = 69869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Paradies für Katalogisierer", description = "<Dok Charly ist außer Atem, als er Euch einen Brief überreicht, der Euch für weiteres Training zurück ins Basislager der Drachenschuppenexpedition einlädt. Er versucht, das Anliegen eifrig zu erklären.>\n\nNetter Elf. Stolzer, winziger Mann. Viele Kameras. Ja?\n\n<Dok Charly nickt aufgeregt, während er auf Eure Antwort wartet.>", sourceObjective = "Sprecht mit Katalogisiererin Coralie im Drachenschuppenbasislager.", completion = "Überall, wo man hinsieht, gibt es faszinierende neue Spezies zu katalogisieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[69870] = { id = 69870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilder mit Bedeutung", sourceObjective = "Trefft Akunda die Katalogisiererin und Kanonierin Fren in der Nähe der Überlaufenden Stromschnellen.", completion = "Ich hoffe mal, dass Ihr Eure Badesachen dabeihabt. Dieser Fluss ist ziemlich wild!", sourceObjectiveStatus = "unverified-source-field" }
