quests[69886] = { id = 69886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orkandrian" }
quests[69888] = { id = 69888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unüblichen Verdächtigen", description = "{name}, Ihr seid hier! Gut. Zeigt keine Reaktion auf das, was ich Euch jetzt sage. Unsere Erkenntnisse über die Titanenscheiben wurden gerade gestohlen! Abgesehen von uns wissen nur die Splitterflammen, was wir in dieser Einrichtung vorhaben.\n\nIch möchte, dass Ihr mit diesem Gerät einige verdächtige Mitglieder untersucht, die uns vor Kurzem beigetreten sind. Findet den Spion und holt so viele Daten zurück, wie Ihr könnt. Wir dürfen nicht zulassen, dass sie in ihre Hände gelangen.", sourceObjective = "Scannt verdächtige Forscher, um den Spion zu enthüllen.", completion = "Entkommen? Das ist nicht gut. Die Splitterflammen waren uns die ganze Zeit schon einen Schritt voraus, und jetzt ist unser einziger Vorteil dahin!\n\nGlücklicherweise habe ich eine Kopie unserer Erkenntnisse angefertigt. Ich gehe gern Risiken ein, aber ich habe gelernt, vorsichtiger zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[69891] = { id = 69891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lepidoralia der Prunkvolle" }
quests[69892] = { id = 69892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollrüssel" }
quests[69895] = { id = 69895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschworener Zerstörer" }
quests[69896] = { id = 69896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unglücklicher Umweg", description = "Ich wusste, dass ich mich in Gefahr begeben würde, wenn ich der Drachenschuppenexpedition beitrete. Aber ich hatte nicht damit gerechnet, gegen Elementare kämpfen zu müssen!\n\nAn unserer Ausgrabung, den Ruinen des Lebensgewölbes, herrscht das pure Chaos! Steinerne Monstrositäten steigen aus dem Boden empor! Wir haben eine Elementaristin zu unserer Beratung angefordert, aber ich glaube, sie wird jede Hilfe brauchen, die sie bekommen kann.\n\nVielleicht könntet Ihr das übernehmen? Unser Lager liegt gleich jenseits des Flusses.", sourceObjective = "Trefft Elementaristin Taiyang in den Ruinen des Lebensgewölbes.", completion = "Danke, dass Ihr gekommen seid! Die Expedition braucht dringend Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[69897] = { id = 69897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhaltensanalyse-\"Hausaufgaben\"", description = "Ich muss mit jemandem sprechen, der sich mit Protowelpen auskennt. Wie die, die im Wildreservat leben!\n\nSind die so wütend wie die Großen? Beißen die oder spucken sie Feuer auf einen?\n\nWas wäre, wenn ich... äh... IHR einen Protowelpen streicheln würdet? Würden sie wissen, dass Ihr nett seid und ihnen zu helfen versucht?\n\nIch frage für die Wissenschaft, natürlich. Tyrgon sagt uns immer, dass wir unsere Hypa.. nein... Hippo... hmpf! Hippothresen... hnn! THEORIEN auf die Probe stellen sollen!\n\nIch glaube, dass sie gerne gestreichelt werden wollen und dass sie sich dann besser fühlen würden. Könntet Ihr das für mich untersuchen?", sourceObjective = "Streichelt 3 schlafende Welpen und meldet Euch dann wieder bei Iyali.", completion = "Also manche Babyprotowelpen werden gern gestreichelt und manche wiederum nicht?\n\nDas ist nicht gut. Was ist, wenn das da seine Freunde ruft? Oder gemein ist?\n\nDiese Lektion, also... das macht keinen Sinn! Meine Hausaufgabe ist äußerst komplex.\n\nDanke, dass Ihr mir geholfen habt. Und es tut mir leid, wenn Ihr verletzt wurdet...", sourceObjectiveStatus = "unverified-source-field" }
quests[69898] = { id = 69898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleisch mit einer Portion Wissenschaft", description = "Äh, ja, also ich, ich habe noch mehr Hausaufgaben... Professor Tyrgons Stunden sind echt schwer! Jetzt soll ich rausfinden, was Protowelpen, äh, fressen! Jawohl...\n\nWartet, ich kenne die Antwort darauf. Sie fressen Flussbestien!\n\nKönnt Ihr mir ein Stück Flussbestienfleisch bringen? Es wäre perfekt, zu \"Anschauungszwecken\" etwas Flussbestienfleisch für mein Projekt zu haben.\n\nEs muss aber ein WIRKLICH gutes Stück sein, okay? Ich meine... wie von den dicklichen Flussbestien. So eins, was ein Mamaprotodrache anschleppen würde, um die Protowelpen richtig stark zu machen, weil... äh... es Herr Tyrgon so glücklich macht.", sourceObjective = "Sammelt 1 Stücke extraleckeres Flussbestienfleisch.", progress = "Meine Mama hat gesagt, dass sich alle über Essen freuen.\n\nVielleicht freundet sie sich so mit mir an...\n\nIch meine, vielleicht freunden sich so alle mit mir an! Und vielleicht gibt Professor Tyrgon mir keine schlechte Note, wenn ich Fleisch einer Flussbestie zum Teil meines Projekts mache!", completion = "Oh, wow! Das ist das am leckersten aussehende Fleisch, das ich JE gesehen habe! Mein Projekt wird die BESTE Note bekommen. Der Protowelpe wird sich sicher darüber freuen!\n\n<Iyalis Ausdruck ist plötzlich voller Besorgnis.>\n\nOh, nein!\n\nIch meine, äh, alle werden versuchen, mich zu kopieren... für das Projekt!\n\n<Iyali lächelt nicht besonders überzeugend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[69899] = { id = 69899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Forschung", description = "Ich weiß, dass ich mich komisch verhalte. Tut mir leid!\n\nIhr habt Euch vermutlich schon gedacht, dass ich nicht die ganze Wahrheit sage.\n\nIch kann Euch von meinem Geheimnis erzählen... wenn Ihr wollt. Aber Ihr müsst versprechen, den Erwachsenen nichts zu verraten.", sourceObjective = "Helft Iyali und ihren Freunden.", progress = "Wir haben diesen verletzten Protowelpen im Wildreservat gefunden.\n\nEin böser Primalist hat Protodrachen angegriffen und dabei wurde dieser arme kleine Welpling verwundet!\n\nBitte schreit uns nicht an... Wir wollten nur helfen!", completion = "Was haben sie getan? Ach diese Jünglinge... Wann werden sie es endlich lernen? Sie hätten verletzt werden können... oder gefangen!\n\nDas ist wirklich sehr ernst...", sourceObjectiveStatus = "unverified-source-field" }
quests[69900] = { id = 69900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle identifizieren", description = "Nach dem, was die Kinder gesagt haben, könnte es sein, dass sich ein Primalist im Wildreservat herumtreibt.\n\nDies erfordert eine sofortige Untersuchung.\n\nAndere Forscher haben festgestellt, dass die Primalisten immer wieder Eier und Welpen stehlen, um ihnen Macht einzuflößen und sie zu verderben. Diejenigen, die diesem Prozess nicht standhalten, erleiden einen langsamen Tod... Aber das interessiert die Primalisten nicht sonderlich...\n\nSie müssen raus aus dem Reservat. Kümmert Ihr Euch darum. Ich werde derweil versuchen, die Kinder abzulenken. Sie dürfen nichts davon erfahren.", sourceObjective = "Tötet den experimentierenden Primalisten im Wildreservat.", completion = "Danke, {name}! Ich bin mir sicher, dass das etwas... unangenehm war.\n\nIhr würdet es sicherlich bevorzugen, Eure Aufgaben auf das Erkunden und Erforschen zu beschränken, doch leider müssen wir uns manchmal die Hände schmutzig machen, um die Wildtiere zu beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[69901] = { id = 69901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbeziehen eines Experten", description = "Hat Iyali gesagt, wie lange dieses Wesen schon leidet? Wenn es wegen der Schmerzen nicht mehr essen kann, müssen wir es schnell behandeln.\n\nNormalerweise würde es in einem Lager der Drachenschuppenexpedition die notwendigen Vorräte dafür geben, doch im Grenzland der Dracheninseln kommt man nicht so leicht an Ressourcen. Es gab spürbare Verzögerungen auf den Versorgungsrouten.\n\nAber keine Bange. Das Land wird uns schon versorgen! Wenn Ihr mir Sonnenlichtblumen bringt, kann ich eine Salbe mischen, die den Drachen beruhigt, damit ich ihn besser behandeln kann.", sourceObjective = "Sammelt 5 Sonnenlichtblumen.", completion = "Wundervoll, {name}. \n\nIch hoffe, die Kinder konnten etwas von Euch lernen.\n\nWie kamen sie auf die Idee, wir würden ihnen nicht helfen? Die Hilfe für Wildtiere ist Teil unserer Mission. Oder sollten wir etwa unsere Pädagogik überdenken...?", sourceObjectiveStatus = "unverified-source-field" }
quests[69902] = { id = 69902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theorie in Praxis", description = "{name}, ich benötige Eure Unterstützung...\n\nEs erwartet doch hoffentlich niemand, dass ich hier bastele, den Welpen beruhige, heile und gleichzeitig die Kinder unterrichte! Alles gleichzeitig zu machen, wird wahrlich überschätzt.\n\nNun, Ihr könnt damit anfangen, indem Ihr diese Blumen benutzt. Ich werde einige Minuten Vorbereitungszeit benötigen, um den Protowelpen zu heilen.\n\nHoffentlich ist das dann für die Kinder auch noch... lehrreich.", sourceObjective = "Helft Tyrgon, die Kreatur zu heilen.", progress = "Wie kommen sie nur auf die Idee, dass wir ihnen nicht helfen würden? Das muss ich mir genauer ansehen...", completion = "Gute Arbeit, {name}! Ich hoffe, die Kinder haben eine wichtige Lektion gelernt... oder zumindest eine denkwürdige.\n\nWir passen hier eine Weile auf den Welpling auf, bis wir die beste Gelegenheit finden, ihn in das Reservat zurückzubringen.\n\nIch ernenne Euch außerdem zum mutigen Forscher. Eure Mitarbeit war unverzichtbar für das Überleben dieser Kreatur. Ich würde Euch nur raten, mir das nächste Mal früher Bescheid zu geben, wenn die Kinder wieder etwas Unüberlegtes planen.\n\nWenn Ihr mich jetzt entschuldigt, ich muss meine Erziehungsmethode überdenken. Sie funktioniert offensichtlich nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[69904] = { id = 69904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtig ruhig", sourceObjective = "Findet Norikos Lehrlinge im Lager Antonidas.", completion = "<Der junge Vulpera kratzt sich nervös am Hinterkopf.>\n\nKennen wir Euch? Noriko hat gesagt, wir sollen nicht mit Fremden reden...", sourceObjectiveStatus = "unverified-source-field" }
quests[69910] = { id = 69910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Furorion?", description = "Wie ungewöhnlich.\n\nEbyssian hat gesagt, Furorion würde hier unsere Ankunft erwarten, zusammen mit einem Botschafter von Alexstrasza der Lebensbinderin, Königin der Drachen.\n\nEs sieht einem Drachen nicht ähnlich, ein Versprechen nicht zu halten.\n\nWenigstens ist diese eifrige Drakonide hier, um uns zu empfangen. Würdet Ihr bitte herausfinden, wann die anderen ankommen?", sourceObjective = "Fragt Sendrax, wann die Drachen ankommen sollten.", progress = "Willkommen auf den Dracheninseln, mein Freund!\n\n...Ich glaube, das habe ich schon mal gesagt. Egal! Ich bin einfach froh, dass Ihr hier seid!", completion = "Ich weiß es nicht! Wie gesagt, das ist mein erster Auftrag... Lasst mich kurz nachdenken, was zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[69911] = { id = 69911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschuldigt das Chaos", description = "Ich wünschte, ich könnte Euch besser auf den Dracheninseln begrüßen, aber ich bin nur der Wachposten.\n\n<Sendrax deutet auf den Turm hinter sich.>\n\nIhr könntet versuchen, mit Botschafter Fastrasz im Besucherzentrum zu sprechen. Er kann vielleicht einige Eurer Fragen beantworten, bis die Drachen hier sind.\n\nPasst auf, wo Ihr hintretet. Er hat vor Kurzem Schutt weggeräumt.", sourceObjective = "Helft Botschafter Fastrasz, die Botschaft wieder aufzubauen.", progress = "Botschafter Fastrasz wird sich freuen, Euch kennenzulernen.", completion = "Die Botschaft sieht schon viel besser aus!\n\nIst jeder {race} so hilfreich wie Ihr? Ich kann es kaum erwarten, noch weitere kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[69912] = { id = 69912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein erster echter Notfall!", description = "<Sendrax wirkt verwirrt.>\n\nIch habe nie erlebt, dass Majordomus Selistra zu irgendetwas zu spät kommt, schon gleich gar nicht SO viel zu spät zu SO etwas Wichtigem.\n\nSehr ungewöhnlich...\n\n<Sendrax kommt ein Gedanke.>\n\nIch könnte mein Notsignalfeuer nutzen, um Selistra über Eure Ankunft zu unterrichten. Dann wird man Euch sicherlich sofort begrüßen!\n\nAllerdings habe ich mein Notsignal noch nie abgefeuert...", sourceObjective = "Überredet Sendrax, ihr Notsignal abzufeuern, um die Drachen über Eure Ankunft zu unterrichten.", completion = "Also gut, {name}. Was sagt Ihr? Wollt Ihr an der Seite Eurer neu gefundenen Drachenbekanntschaften kämpfen?\n\nIch versichere Euch, viel schneller könnt Ihr Euch deren Vertrauen nicht verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[69913] = { id = 69913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme irdener Kräfte" }
quests[69914] = { id = 69914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Djaradin sind erwacht", description = "Ich wünschte, wir hätten mehr Zeit für standesgemäße Begrüßungen, aber wir können nicht alle Chronormu sein, stimmt's?\n\nIch bin Selistra, Majordomus von Alexstrasza der Lebensbinderin, Königin der Drachen.\n\nKönigin Alexstrasza hat mich gebeten, ihre besten Grüße zu überbringen und Euch zu ihr bei den Lebensbecken zu eskortieren.\n\nAber ich fürchte, bevor wir zu ihr aufbrechen können, muss ich Euch um Eure Hilfe bitten.\n\nUnsere uralten Rivalen, die Djaradin, sind von ihrem Schlummer unter der Erde erwacht und haben bereits einen nahegelegenen Außenposten überfallen!", sourceObjective = "Erhaltet Eure Befehle von Majordomus Selistra.", progress = "Wir müssen tun, was immer Majordomus Selistra verlangt.", completion = "Die Djaradin sind erwacht? Das ist nicht gut, {name}...", sourceObjectiveStatus = "unverified-source-field" }
quests[69915] = { id = 69915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezielte Werbung", description = "Hi, hi, hi! Seid Ihr auf der Suche nach Aufträgen?\n\nWir veranstalten einen RIESIGEN Eröffnungsverkauf für unseren neuen Handwerksauftragsservice und müssen dafür ordentlich Aufmerksamkeit auf uns ziehen! ...Doch der Wind hat meine Flugblätter davongeweht und ich glaube, ein paar der örtlichen Ziegen sind mit ihnen davongerannt.\n\nKönntet Ihr meine Handzettel zurückbringen?", sourceObjective = "Holt Flugblätter von den Flussgabelziegen und den störenden Ziegen zurück.", completion = "Danke, danke, danke! Ihr seid der Beste, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[69916] = { id = 69916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berühmte Frösche" }
quests[69918] = { id = 69918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschütterung unserer Fundamente", description = "Steinbinder der Djaradin drohen damit, die Fundamente dieses Gebäudes zu zerstören! Wir müssen sie aufhalten!\n\nWir hatten noch nicht einmal die Gelegenheit, die Zitadelle zurückzuerobern, und jetzt steht sie kurz davor, unter unseren Füßen wegzubrechen.\n\nTut, was Ihr könnt, {name}...und damit meine ich: Legt sie um!", sourceObjective = "Tötet Steinbrecherin Tokara, Molka die Schleiferin und die Elementare, die sie entfesselt haben.", completion = "Ich wusste, dass wir uns auf Euch verlassen können. Jetzt, da die Zitadelle nicht mehr einzustürzen droht, geht es mir schon viel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[69919] = { id = 69919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Handwerk in Not", description = "Ihr scheint mir geschickt im Handwerken zu sein. Möchtet Ihr vielleicht ein paar Handwerksaufträge für andere Abenteurer übernehmen und reich, reich, reich werden?\n\nDie Regeln des Handwerkerkonsortiums sind schnell erklärt und dann könnt Ihr an allen Handwerksstationen auf den Dracheninseln Aufträge annehmen!", sourceObjective = "Sprecht mit Azley und erfahrt mehr über das Erfüllen von Handwerksaufträgen.", completion = "Klasse, klasse, klasse! Macht weiter so, es gibt immer noch mehr Aufträge zu erledigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[69923] = { id = 69923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Urbedrohung", description = "Raszageth hat keine Zeit verschwendet, ihre Primalistenstreitkräfte auszubauen.\n\nDie Kirin Tor haben massive Stürme entdeckt, die an Schlüsselpunkten in Kalimdor und den Östlichen Königreichen freigesetzt werden.\n\nDie Primalisten entfesseln die Elemente, um ihre Macht zu stärken. Es scheint, als hätten sie nicht nur auf den Dracheninseln, sondern auch in den Ländern der Allianz und der Horde vor, Chaos zu stiften.\n\nSucht den Feind auf und studiert seine Methoden. Wir müssen ihn aufhalten, bevor es zu spät ist.", sourceObjective = "Sammelt 10 Partikel urtümlicher Energie von Gegnern an Orten aktiver Urstürme in Kalimdor und den Östlichen Königreichen.", progress = "Ich fürchte, das ist erst der Anfang.", completion = "Zum Glück konntet Ihr ihren Angriff vereiteln, zumindest für den Moment.\n\n<Khadgar untersucht die Partikel, die Ihr ihm gebracht habt.>\n\nHmm, Urelementarenergie. Ich werde das genauer studieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[69924] = { id = 69924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme flammender Kräfte" }
quests[69925] = { id = 69925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stürme beruhigen", description = "Diese Primalisten sind erbarmungslos und entfesseln elementare Verwüstung in den Östlichen Königreichen und Kalimdor.\n\nIhr müsst genau so viel Entschlossenheit zeigen, {name}. Das ist der einzige Weg, sie aufzuhalten.\n\nFindet heraus, wo sie als Nächstes eindringen, entfernt die Gegner im Gebiet des Ursturms, bevor es zu spät ist, und macht ihre Pläne zunichte.\n\nWir müssen Azeroth beschützen!", sourceObjective = "Sammelt 10 Partikel urtümlicher Energie von Gegnern an Orten aktiver Urstürme in Kalimdor und den Östlichen Königreichen.", progress = "Unsere Arbeit geht weiter.", completion = "Gut gemacht. Hoffen wir, dass uns das bis zu ihrem nächsten Eindringen etwas Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[69926] = { id = 69926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabrina Schwarz und die sieben Gnome", description = "Die Djaradin haben die Obsidianzitadelle geplündert und dabei einige wertvolle Artefakte gestohlen.\n\nFurorion hat uns aufgetragen, jedes aus der Zitadelle entwendete Artefakt zurückzubringen. Mein Team hat in der Umgebung mehrere ausfindig gemacht, wir könnten allerdings Eure Hilfe brauchen.", sourceObjective = "Holt die gestohlenen Artefakte zurück.", progress = "Habt Ihr alles auf der Liste finden können?", completion = "Ausgezeichnete Arbeit, {name}. Wir melden uns bei Euch, sobald wir mehr der gestohlenen Artefakte aufgespürt haben und wieder Eure Hilfe brauchen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[69927] = { id = 69927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bazual" }
quests[69928] = { id = 69928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liskanoth" }
quests[69929] = { id = 69929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strunraan" }
quests[69930] = { id = 69930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basrikron" }
quests[69931] = { id = 69931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Sturzflug schnappen" }
quests[69932] = { id = 69932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jedes Leben zählt", description = "Tränke für Gelikyr herzustellen, bedeutet, dass ich keine Zeit für meine anderen Pflichten habe.\n\nIn meinem Garten ist eine Ente mit einer gebrochenen Rippe gelandet. Ich habe ihre Wunde behandelt, aber der Verband müsste gewechselt werden. Und da Ihr so erpicht darauf seid, zu helfen...\n\n<Szareth drückt Euch eine Liste mit Zutaten in die Hand.>\n\nDies werdet Ihr brauchen. Bringt den Rest bitte zu mir.", sourceObjective = "Sammelt Zutaten, um den Verband des kleinen Strahlstroms zu ersetzen.", progress = "Also?", completion = "<Szareth nimmt die zusätzlichen Pollen und das Leinen und schaut dann zur Hütte.>\n\nEnten müssen sich bei den Klippen weiter oben gegen Harpyien behaupten. Die Verwundeten landen hier, wo ich sie, so gut ich kann, verarzte.\n\nIch hoffe, dass diese hier es schafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[69933] = { id = 69933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis der Neugier", description = "Schaut über die Schlucht, {race}. Primalisten haben vor Tagen den Posten der Gelikyr angegriffen, und der Kampf hat noch kein Ende gefunden.\n\nDie Leute brauchen Salben und müssen genäht werden. Ich kann alles Nötige herstellen, aber langsam gehen mir die Zutaten aus. Da Ihr Euch dazu entschlossen habt, in mein Heim einzudringen, betrachtet Euch als <Freiwilliger/Freiwillige>.\n\nGeht zu meinem Garten und schnappt Euch die größte Ranke, die Ihr finden könnt. Brecht sie an der Wurzel ab und bringt sie dann zu mir.", sourceObjective = "Nehmt einen Ableger von der robusten Ranke.", progress = "Beeilt Euch, eine frische Zutat ist eine mächtige Zutat.", completion = "Der Peitscher hat Euch angegriffen?\n\n<Szareth runzelt die Stirn, schnüffelt an Eurer Kleidung und verzieht angewidert die Schnauze.>\n\nKein Wunder... Ihr stinkt nach Blut. Und zwar nicht nach Eurem, nehme ich mal an.\n\nKrieg macht sich auf den Inseln breit.", sourceObjectiveStatus = "unverified-source-field" }
quests[69934] = { id = 69934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutende Herzen", description = "Die Tränke sind fertig, jetzt müssen sie nur noch geliefert werden.\n\nBringt eine Kiste zu einer kleinen Höhle in der Schlucht unter uns. Es wird niemand da sein, um sie entgegenzunehmen, aber seid Euch sicher, dass sie dort guten Nutzen findet.\n\nBringt die nächste Kiste zum Lazarett im Posten der Gelikyr. Ein alter Freund kümmert sich dort um die Patienten.\n\nIch... weiß, dass das nicht Eure Aufgabe ist. Und die meine ist es auch nicht wirklich. Aber Ihr wart erstaunlich hilfreich, und diese Medizin könnte Leben retten.", sourceObjective = "Überbringt die medizinischen Vorräte.", progress = "Verzeiht, ich habe gerade keine Zeit zum Reden.", completion = "Szareth will jeden heilen, ungeachtet der Konsequenzen. Rebellen, Eidschuppen, Wildtiere: alle verdienen gleichermaßen Fürsorge.\n\nUnd auch wenn mir dieser Idealismus zuwider ist, ist Gelikyr gerade auf Szareths Fähigkeiten angewiesen.\n\nRichtet Szareth also meinen Dank aus... und Euch natürlich auch vielen Dank. Diese Tränke sind von unschätzbarem Wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[69936] = { id = 69936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obervandale Zambul", description = "Gute Arbeit. Diese Schänder können meine Ahnen nicht mehr dazu zwingen, für sie zu kämpfen. Wir müssen uns aber noch um den Wüstling kümmern, der ihnen Befehle zuruft.\n\nDas ist ihr Aufseher, Zambul. Er muss aufgehalten werden.\n\nErledigt ihn.", sourceObjective = "Bezwingt Aufseher Zambul.", progress = "Habt Ihr Zambul sein verdientes Ende bereitet?", completion = "Ein Initiand darf sich nicht über den Tod eines anderen Maruuk freuen. Aber bei Zambul sieht die Sache anders aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[69937] = { id = 69937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvanbeistand", description = "Ah, {name}, da seid Ihr ja! Ich suche Euch schon überall.\n\nSchon wieder hat eins unserer hiesigen Kleintiere in letzter Zeit keine Leckerlis bekommen. Zieht doch mal los und findet was Süßes zum Anbeißen, was meint Ihr?", sourceObjective = "Beschafft einen schmackhaften Schlüpflingschmaus und gebt ihn dem verzweifelten Entchen.", completion = "Ein neuer Tag, ein neues entzücktes Freundchen! Ausgezeichnete Arbeit, mein Sylvanlehrling!", sourceObjectiveStatus = "unverified-source-field" }
quests[69938] = { id = 69938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelwahnsinn!" }
quests[69939] = { id = 69939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvanbeistand", description = "Ah, {name}, da seid Ihr ja! Ich suche Euch schon überall.\n\nSchon wieder hat eins unserer hiesigen Kleintiere in letzter Zeit keine Leckerlis bekommen. Zieht doch mal los und findet was Süßes zum Anbeißen, was meint Ihr?", sourceObjective = "Beschafft Schnee im Hörnchen und gebt ihn dem erschöpften Otter.", completion = "Ein neuer Tag, ein neues entzücktes Freundchen! Ausgezeichnete Arbeit, mein Sylvanlehrling!", sourceObjectiveStatus = "unverified-source-field" }
quests[69940] = { id = 69940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvanbeistand", description = "Ah, {name}, da seid Ihr ja! Ich suche Euch schon überall.\n\nSchon wieder hat eins unserer hiesigen Kleintiere in letzter Zeit keine Leckerlis bekommen. Zieht doch mal los und findet was Süßes zum Anbeißen, was meint Ihr?", sourceObjective = "Beschafft einen Walrossmuffin und bringt ihm dem ängstlichen Molch.", completion = "Ein neuer Tag, ein neues entzücktes Freundchen! Ausgezeichnete Arbeit, mein Sylvanlehrling.", sourceObjectiveStatus = "unverified-source-field" }
quests[69941] = { id = 69941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingefrorene Opfer" }
quests[69942] = { id = 69942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brackenfellmysterien" }
quests[69944] = { id = 69944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmjagd", description = "Nun, der Zauberer weiß auf jeden Fall, wie man einen gewaltigen Auftritt hinlegt, nicht wahr?\n\nWir können nicht in See stechen, bis jemand diese Elementarstürme in den Griff bekommt.\n\nWendet Euch an Sturmjägerin Suhrakka. Sie ist im Rahmen der Expedition für die Erforschung der Stürme verantwortlich und kann Euch sicher mit der nötigen Ausrüstung ausstatten.\n\nIch koordiniere derweil die übrigen Vorbereitungen. So kann ich wenigstens ein paar Bände zur Drachengeschichte studieren, bevor wir aufbrechen.", sourceObjective = "Sprecht mit Sturmjägerin Suhrakka am Zeppelinturm.", completion = "Diese Stürme sind wilde und gefährliche Erscheinungen. Wenn Ihr sie angehen wollt, werdet Ihr zusätzlichen Schutz benötigen.\n\nIch war in meinem Leben schon auf vielen Jagden und dabei habe ich viele Dinge gesammelt, die vor dem Zorn der Elemente schützen. Vielleicht könnte sich eines dieser Objekte ja auch für Euch als nützlich erweisen?", sourceObjectiveStatus = "unverified-source-field" }
quests[69946] = { id = 69946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Meisterin ihres Fachs", description = "Als ich diese Ebenen bereiste, traf ich eine alte Zentaurin in einer Höhle im Norden, die ihr Handwerk offensichtlich gemeistert und weise Ratschläge parat hatte.\n\nSie hat mir geholfen, das Erlernte von den Dracheninseln besser zu verstehen.\n\nWenn Ihr Euch in Eurem Beruf spezialisieren möchtet, sucht diese Meisterin des Wissens auf. Sie hieß Khadin und gehörte zum Klan Teerai.", sourceObjective = "Sucht Meisterin Khadin auf und befragt sie zu ihrer beruflichen Weisheit.", progress = "Geduld, junges Wesen. Seid beruhigt zu wissen, dass es viel zu lernen gibt, und das ist annehmbar.", completion = "Wenn Ihr Euch wirklich für mein Wissen interessiert, müsst Ihr Euch dessen würdig erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[69949] = { id = 69949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslöschung" }
