quests[69964] = { id = 69964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgebrachter Elementar" }
quests[69965] = { id = 69965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Qualitätssicherung", description = "Sucht Ihr nach Arbeit, {class}?\n\nIch vertrete eine neues Handelsunternehmen, das Handwerkerkonsortium, das Handwerker und deren Kunden über unser Netzwerk von Handwerksaufträgen verbindet.\n\nDie Drachenschuppenexpedition hat eine Bestellung für einige verzauberte Bergbauwerkzeuge aufgegeben. Die Werkzeuge sind fertig, aber wir würden sie gerne testen, bevor wir die Bestellung abschließen.\n\nWir werden Euch natürlich für Eure Dienste bezahlen.", sourceObjective = "Testet Haephestas Werkzeuge an Geoden in der Nähe für das Handwerkerkonsortium.", completion = "Vielen Dank für Eure Hilfe, {name}.\n\nSolltet Ihr je etwas Bestimmtes brauchen, kann das Handwerkerkonsortium es für Euch herstellen.", sourceObjectiveStatus = "unverified-source-field" }
