quests[69976] = { id = 69976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phenran" }
quests[69979] = { id = 69979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd der Würde", description = "Man erhält nicht einfach Weisheit, man erarbeitet sie sich. Wenn Ihr wünscht, Euch als würdig zu beweisen, dann werdet Ihr das auf die gleiche Art wie der Rest meines Volkes machen und es in der Praxis lernen.\n\nFindet und erlegt den Bullenältesten Tausendmeilen, der sich unserer Jagd schon seit Generationen entzieht.\n\nDas wird Euch die Weisheit verleihen, nach der Ihr sucht.", sourceObjective = "Erlegt den Bullenälteste Tausendmeilen.", progress = "Kehrt Ihr siegreich zurück? Eine große Jagd verspricht große Belohnungen.", completion = "Der Weg zur Meisterschaft ist langsam, aber stetig. Ihr solltet die Reise ehren\n\nWenn Ihr zusätzliche Weisheit sucht, dann bleibt der guten Jagd treu. In dieser Welt wird es immer etwas zu tun geben. Es wird immer Kreaturen geben, die gejagt werden wollen und von denen wir lernen können.\n\nUnd ich werde hier sein, um Euch dabei zu helfen, dieses Wissen zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[69980] = { id = 69980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeranke: Angler Tinnaks Geschenk", description = "<Ihr seht, wie die Spektralhand des armen Fischers immer noch einen Faden hält, der aus sehr starkem und doch leichtem Tang gewoben wurde. Nunvuq in Iskaara könnte ihn vielleicht brauchen.>", sourceObjective = "Bringt das Seil aus Seeranken zu Nunvuq in Iskaara.", sourceObjectiveStatus = "unverified-source-field" }
quests[69981] = { id = 69981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kundenzufriedenheit", description = "Hey, {class}, habt Ihr kurz Zeit, bei etwas zu helfen?\n\nEinige unserer Stammkunden haben Umfertigungen beim Handwerkerkonsortium in Auftrag gegeben, aber wir haben schon seit einer Weile nichts mehr von ihnen gehört.\n\nWenn Ihr ihnen über den Weg lauft, dann stellt doch bitte fest, ob sie mit ihren Einkäufen zufrieden sind, ja? Man muss die Kunden glücklich, glücklich, glücklich machen!", sourceObjective = "Fragt die Kunden des Handwerkerkonsortiums, ob sie mit ihren Umfertigungen zufrieden sind.", progress = "<Mahra pfeift vor sich hin, während sie arbeitet.>", completion = "Oh nein! Sie seien gesegnet... <Mahra überprüft die Ausrüstung>.\n\nAlles ruiniert, zu lange den Elementen ausgesetzt.\n\nHier, nehmt das und stellt neue Rüstungen her. Oder sprecht mit einem der Verwaltungsangestellten für Handwerksaufträge neben mir oder in Valdrakken, um das von jemand anderem machen zu lassen. Ich empfehle etwas für Eure Handgelenke oder Brust.\n\nEins noch... die Qualität dieser Zutaten ist nicht besonders gut, aber Ihr könnt Eure neue Ausrüstung jederzeit umfertigen lassen, um ihre Qualität zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[69983] = { id = 69983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammengeschnitzter Knochen", description = "<Geheimnisvolle Djaradinrunen, die in einen Knochen geschnitzt wurden. Krallenpirscherin Kavia würde sich das bestimmt ansehen wollen.>", sourceObjective = "Bringt den Gegenstand zu Krallenpirscherin Kavia.\n\nBereitgestellter Gegenstand:", completion = "Das könnte wichtig sein. Danke, dass Ihr ihn mir gebracht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[69984] = { id = 69984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldgefasster Drachenzahn", description = "<Ihr seid auf den Überrest eines gefallenen Drachen gestoßen. Exadria wird ihn sicher sehen wollen.>", sourceObjective = "Bringt den Gegenstand zu Exadria.\n\nBereitgestellter Gegenstand:", completion = "Es ist wichtig, dass dieser Drache nicht vergessen wird. Danke, dass Ihr ihn mir gebracht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[69987] = { id = 69987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Wildheit, die Zweite: Schrecken des Sumpfes!" }
