quests[69991] = { id = 69991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Wildheit, die Zweite: Gegner aus dem Vulkan!" }
quests[69992] = { id = 69992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Stürme", description = "<Jemand mit großem magischen Wissen würde so etwas sicherlich gerne studieren wollen.>", sourceObjective = "Bringt das Siegel der Stürme zu Sturmjägerin Suhrakka in Durotar.\n\nBereitgestellter Gegenstand:", completion = "Was die Magie angeht, übersteigt das mein Wissen leider deutlich.\n\nAber ich werde es zu Khadgar bringen. Gebietet Ihr weiter der Bedrohung durch die Primalisten Einhalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[69993] = { id = 69993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Wildheit, die Zweite: Verloren im Traum!" }
