quests[70021] = { id = 70021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sage von Tapionnuq" }
quests[70025] = { id = 70025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Drakoniumsichel", description = "Ihr wirkt, als hättet Ihr nicht viel zu tun. Wie sieht's aus mit ein bisschen Arbeit?\n\nDas Handwerkerkonsortium hat bei mir eine Drakoniumsichel in Auftrag gegeben. Natürlich könnte ich die im Handumdrehen schmieden, aber in meinen Augen ist das eher was für Lehrlinge.\n\nFertigt die Sichel und bringt sie zum Rubinlebensschrein. Eine Draenei namens Haephesta wird Euch entlohnen.", sourceObjective = "Liefert eine Drakoniumsichel an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70026] = { id = 70026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Lavakäfer", description = "Seid Ihr auf der Suche nach Arbeit, <Kräuterkundiger/Kräuterkundige>? Ich soll für die Kunden des Handwerkerkonsortiums ein paar Käfer sammeln.\n\nDas Land wimmelt zwar nur so vor Lebewesen, doch auch dieser Auftrag erfordert Zeit.\n\nKönntet Ihr ein paar Käfer mitbringen, wenn Ihr draußen umherstreift?", sourceObjective = "Liefert 5 Lavakäfer an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70027] = { id = 70027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Stoffbänder des Inspektors", description = "Sucht Ihr Arbeit, <Schneider/Schneiderin>? Das Handwerkerkonsortium hat mich gebeten, Gelenkbänder für deren Kunden zu fertigen.\n\nIch weiß zu schätzen, dass die Forschersleute auf unsere Webarbeiten neugierig sind, doch mir fehlt die Zeit.\n\nHättet Ihr möglicherweise Interesse?", sourceObjective = "Liefert Stoffbänder des Inspektors an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70028] = { id = 70028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Salzvorkommen", description = "Lust auf Arbeit, <Bergarbeiter/Bergarbeiterin>?\n\nIch hab mich mit Haephesta unterhalten und die meinte, das Handwerkerkonsortium braucht Salz für seine Kunden.\n\nIch würde ja selbst was schürfen, aber, na ja, mir fehlt die Motivation.\n\nSeid doch so nett und besorgt ihnen welches!", sourceObjective = "Liefert 5 Salzvorkommen an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70029] = { id = 70029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Runenverzierte Serevitruten", description = "Ihr scheint ein magisches Händchen zu haben, <Verzauberer/Verzauberin>. Könntet Ihr mir bei einem Auftrag helfen?\n\nDas Handwerkerkonsortium hat für einen Kunden mehrere Ruten aus Serevit angefordert, aber das Verzaubern von Ruten ist nicht gerade mein Spezialgebiet.\n\nWenn Ihr Euch darum kümmern wollt, wird Euch Haephesta beim Rubinlebensschrein für Eure Mühe entlohnen!", sourceObjective = "Liefert 2 runenverzierte Serevitruten an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70030] = { id = 70030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Qualitätsgesichertes Optikmodul", description = "Ah, <ein Ingenieur/eine Ingenieurin>, und grade zur rechten Zeit!\n\nIch muss ein paar Baupläne überarbeiten, aber eine große Frau ist vorbeigeschneit und wollte ein Optikmodul haben.\n\nIhr kennt Euch doch mit so was aus, oder?\n\nBringt es zum Rubinlebensschrein, wenn Ihr es fertighabt. Sie hat irgendwas vom Handwerkerkonsortium erzählt.", sourceObjective = "Liefert ein qualitätsgesichertes Optikmodul an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70031] = { id = 70031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Glattes Nudelholz des Kochs", description = "Seid Ihr auf der Suche nach einer bezahlten Beschäftigung, <Inschriftenkundiger/Inschriftenkundige>?\n\nEine Gesellschaft namens Handwerkerkonsortium ist mit einem Auftrag an mich herangetreten.\n\nDieser könnte für einen Lehrling wie Euch genau das Richtige sein.", sourceObjective = "Liefert ein glattes Nudelholz des Kochs an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70032] = { id = 70032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Juweliersbrille", description = "Sucht Ihr Arbeit, <Juwelenschleifer/Juwelenschleiferin>? Das Handwerkerkonsortium hat mich gebeten, eine Brille für deren Kunden herzustellen.\n\nMich! Als ob ich Zeit für diesen Nonsens hätte.\n\nIhr könnt das doch übernehmen, oder?", sourceObjective = "Liefert Kopflupen aus gesplittertem Onyx an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70033] = { id = 70033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Lederstiefel des Pioniers", description = "Auf der Suche nach Arbeit, <Lederverarbeiter/Lederverarbeiterin>? Das Handwerkerkonsortium will ein Paar Stiefel für seine Kundschaft von mir.\n\nDie wissen anscheinend nicht, wie gefragt ich bin. Wisst Ihr, wie viele Forschersleute allein heute mit löchrigem Schuhwerk vorbeigekommen sind?\n\nNehmt diese Maße, falls Ihr Zeit habt. Vielleicht kann man mit diesem Konsortium ja gut Geschäfte machen.", sourceObjective = "Liefert Lederstiefel des Pioniers an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70034] = { id = 70034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerversorgung: Salamantherschuppen", description = "Braucht Ihr Arbeit, <Kürschner/Kürschnerin>? Ich soll für die Kunden des Handwerkerkonsortiums die Schuppen eines Salamanthers sammeln.\n\nIch mag Handwerkerin sein, aber die Botengänge können sie allein unternehmen!\n\nAber... ach, vielleicht könnt Ihr ja welche auftreiben?", sourceObjective = "Liefert 3 Salamantherschuppen an Haephesta beim Rubinlebensschrein.", progress = "Womit kann das Handwerkerkonsortium Euch heute behilflich sein?", completion = "Eine Lieferung! Ausgezeichnet! Es ist mir eine Freude, Geschäfte mit Euch zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70035] = { id = 70035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruriqs Stromschnellenritt" }
quests[70037] = { id = 70037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energielose Werkzeuge" }
quests[70040] = { id = 70040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturz durch die Zeit", description = "Als die Magie der Bronzenen mit der der Ewigen kollidierte, beförderte sie Chronormu und Eternus in einen unkontrollierten Sturz durch die Zeit.\n\nWährend sie fallen, zerreißen sie das Gewebe der Zeit selbst und senden zahllose Wellen durch Raum und Zeit. Wir müssen sie aufspüren und zurückholen. Nur so können wir weitere Schäden vermeiden. Ich sehe, dass Ihr Chronormus Fall beenden werdet.\n\nIch würde Euch bitten, die Verbündeten zu versammeln, die Ihr braucht, um Chronormu zu retten. Ich werde mich unterdessen auf ihre Magie konzentrieren.", sourceObjective = "Versammelt Eure Verbündeten und sprecht anschließend mit Nozdormu.", progress = "Schnell. Nicht einmal wir dürfen Zeit verschwenden.", completion = "Wenn wir schnell handeln, können wir sie vielleicht auffangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70041] = { id = 70041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Sturmfresserin", description = "Raszageth versucht, alle Arkanmagie aus dem Turm zu ziehen, sodass sie ihn zerstören kann!\n\nKalecgos tut, was er kann, um sie aufzuhalten, und ich versuche, mit meiner Magie die Leyenergie wiederherzustellen.\n\nIch fürchte, wir halten nicht mehr viel länger durch. Genau in diesem Moment befinden sich weitere Primalisten auf dem Weg hier hoch, um uns zu überwältigen!\n\nNehmt meine modifizierte Arkanscheibe. Haltet die eintreffenden Primalisten auf... und lasst uns auf ein Wunder hoffen.", sourceObjective = "Nutzt Khadgars Flugscheibe und haltet die Primalistenarmee auf.", completion = "Raszageth ist geflohen, der Vakthros stabilisiert... und mehr blaue Drachen sind angekommen.\n\nIch glaube, wir können uns einen Moment ausruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70042] = { id = 70042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Menge Möglichkeiten", description = "Ihr habt mir einen Schrecken eingejagt, ich dachte schon, ich wäre erwischt worden!\n\nSchaut Euch die ganzen mutigen Forscher an, bereit die Dracheninseln zu erobern... Taschen voller Werkzeuge und Ausrüstung.\n\nWir könnten hier reich werden!\n\nSeht Euch um, ob Ihr einige Gegenstände in die Finger bekommt, und ich teile den Profit mit Euch.", sourceObjective = "Besorgt mehrere Gegenstände für Wisch den Schleicher.", progress = "Habt Ihr gefunden, was wir suchen?", completion = "Ich hab doch gesagt, wir machen Gewinn.", sourceObjectiveStatus = "unverified-source-field" }
